// ABOUTME: Real-Chrome regressions for automatic overlay dismissal and verified click targeting.
// ABOUTME: Local synthetic pages record button events so unintended actions never affect an account.
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { BrowserPage } from '../../src/core/page.js';
import { CdpConnection, type CdpSession } from '../../src/core/steel/cdp.js';
import { announceMissing, findChrome, HeadlessChrome, until } from '../helpers/headless-chrome.js';

const chromePath = findChrome();
announceMissing('action safety browser suite', chromePath ? [] : ['Google Chrome']);
let chrome: HeadlessChrome | undefined;
let connection: CdpConnection | undefined;
let session: CdpSession;
let page: BrowserPage;

beforeAll(async () => {
    if (!chromePath) return;
    chrome = await HeadlessChrome.launch(chromePath);
    connection = await CdpConnection.connect(chrome.debuggerUrl);
    session = await connection.attachToPage();
    page = await BrowserPage.attach(session, {
        budgets: { navigationWatchMs: 5, navigationMs: 100, mutationQuietMs: 5, mutationMaxMs: 100 },
    });
}, 150_000);

afterAll(async () => {
    await connection?.close();
    await chrome?.close();
});

async function load(body: string): Promise<void> {
    const html = `<html><head><style>button { position:absolute; left:100px; top:100px; width:180px; height:50px } [role=dialog] { position:fixed; inset:0; } #cover { z-index:100; }</style></head><body>${body}<script>window.actions=[];for(const b of document.querySelectorAll('button')) b.onclick=()=>window.actions.push(b.id);</script></body></html>`;
    await page.navigate(`data:text/html,${encodeURIComponent(html)}`);
    await until(
        'fixture ready',
        async () =>
            (
                await session.send<{ result: { value: boolean } }>('Runtime.evaluate', {
                    expression: 'Array.isArray(window.actions)',
                    returnByValue: true,
                })
            ).result.value,
        Boolean
    );
}

async function actions(): Promise<string[]> {
    return (
        await session.send<{ result: { value: string[] } }>('Runtime.evaluate', {
            expression: 'window.actions',
            returnByValue: true,
        })
    ).result.value;
}

const CONSENT =
    '<div role="dialog" aria-label="Cookie consent"><p>Choose your cookie consent preferences.</p><button id="accept">Accept all cookies</button></div>';

describe.skipIf(!chromePath)('safe automatic dismissal', () => {
    it.each(['Continue to payment', 'Accept all cookies', 'Save'])(
        'does not click an ordinary %s control',
        async label => {
            await load(`<button id="ordinary">${label}</button>`);
            await page.act({ action: 'dismiss_overlays' });
            expect(await actions()).toEqual([]);
        }
    );

    it('dismisses a genuine consent dialog', async () => {
        await load(CONSENT);
        await page.act({ action: 'dismiss_overlays' });
        expect(await actions()).toEqual(['accept']);
    });

    it('refuses a covered consent button just like a normal click', async () => {
        await load(`${CONSENT}<button id="cover">Delete account</button>`);
        await expect(page.act({ action: 'dismiss_overlays' })).rejects.toMatchObject({ code: 'click_blocked' });
        expect(await actions()).toEqual([]);
        await expect(page.act({ action: 'click', target: '#accept' })).rejects.toMatchObject({ code: 'click_blocked' });
        expect(await actions()).toEqual([]);
    });
});

// ABOUTME: Reads a page whose form lives two iframes down in a real headless Chrome, so the frame
// ABOUTME: descent and the page-coordinate maths are executed against the browser, not against a fake.
import { createServer, type Server } from 'node:http';
import type { AddressInfo } from 'node:net';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { PageState, type SnapshotNode } from '../../src/core/snapshot.js';
import { CdpConnection, type CdpSession } from '../../src/core/steel/cdp.js';
import { announceMissing, findChrome, HeadlessChrome, until } from '../helpers/headless-chrome.js';

const chromePath = findChrome();
const available = chromePath !== null;
announceMissing('the frame snapshot browser suite', available ? [] : ['Google Chrome']);

/** The launch, the CDP handshake and the first navigation all live inside this one hook. */
const BROWSER_SETUP_TIMEOUT_MS = 150_000;

/** The form control the test looks for, three documents down from the page the caller navigated to. */
const FIELD_LABEL = 'Address';

/** Scrolls the page and every frame in it, so all three scroll terms of the placement are non-zero. */
const SCROLL_ALL =
    '(function scrollAll(w) { w.scrollTo(0, 60);' +
    " for (const f of w.document.querySelectorAll('iframe')) { try { scrollAll(f.contentWindow); } catch {} } })(window)";

let server: Server | undefined;
let chrome: HeadlessChrome | undefined;
let connection: CdpConnection | undefined;
let session: CdpSession | undefined;
let origin = '';

beforeAll(async () => {
    if (!available) return;
    server = await startFixtureServer();
    origin = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;

    chrome = await HeadlessChrome.launch(chromePath!);
    connection = await CdpConnection.connect(chrome.debuggerUrl);
    session = await connection.attachToPage();
    await session.send('Page.enable');
    await session.send('Page.navigate', { url: `${origin}/service` });
    // The innermost frame is written by script, so a load event on the top document proves
    // nothing, and counting documents proves little more: the frame exists as `about:blank` before
    // its real document arrives. The frame is ready when that document has finished loading.
    await until(
        'the form frame to finish loading its fields',
        () => innerFrameReady(session!),
        ready => ready,
        30_000
    );
    // Every frame carries a border and padding, and the innermost one is scrolled, so the placement
    // maths is checked against Chrome with all three terms non-zero.
    await session.send('Runtime.evaluate', { expression: SCROLL_ALL });
    await until(
        'the inner frame to report its scroll position',
        () => innerScrollTop(session!),
        scrolled => scrolled > 0,
        10_000
    );
}, BROWSER_SETUP_TIMEOUT_MS);

afterAll(async () => {
    if (connection !== undefined) await connection.close();
    if (chrome !== undefined) await chrome.close();
    if (server !== undefined) {
        // A browser keeps its connections alive after the page is gone, and `close` waits for them.
        const closed = new Promise<void>(resolve => server!.close(() => resolve()));
        server.closeAllConnections();
        await closed;
    }
});

describe.skipIf(!available)('PageState.capture in a real browser', () => {
    it('gives a ref to a field two frames below the page that was navigated to', async () => {
        const snapshot = await new PageState().capture(session!, {});
        const field = fieldIn(snapshot.nodes);
        expect(field?.ref, `the snapshot was:\n${snapshot.text}`).toBeDefined();
    });

    it('puts that field where Chrome says it is on the page', async () => {
        const snapshot = await new PageState().capture(session!, {});
        const field = fieldIn(snapshot.nodes);
        expect(field?.center, `the snapshot was:\n${snapshot.text}`).toBeDefined();

        const box = await session!.send<{ model?: { content?: number[] } }>('DOM.getBoxModel', {
            backendNodeId: field!.backendNodeId,
        });
        const quad = box.model?.content ?? [];
        // The box model answers in the top frame's viewport coordinates and the snapshot in the
        // page's, so the comparison adds back how far the top page has scrolled.
        const metrics = await session!.send<{ cssLayoutViewport?: { pageX?: number; pageY?: number } }>(
            'Page.getLayoutMetrics'
        );
        const scrolled = metrics.cssLayoutViewport ?? {};
        expect(scrolled.pageY ?? 0, 'the top page has to be scrolled for this to prove anything').toBeGreaterThan(0);
        const centre = {
            x: (Math.min(quad[0]!, quad[4]!) + Math.max(quad[0]!, quad[4]!)) / 2 + (scrolled.pageX ?? 0),
            y: (Math.min(quad[1]!, quad[5]!) + Math.max(quad[1]!, quad[5]!)) / 2 + (scrolled.pageY ?? 0),
        };
        expect(field?.center?.x).toBeCloseTo(centre.x, 1);
        expect(field?.center?.y).toBeCloseTo(centre.y, 1);
    });

    it('still reads the top document', async () => {
        const snapshot = await new PageState().capture(session!, {});
        expect(snapshot.nodes.some(node => node.name === 'Start a service request')).toBe(true);
    });

    it('reports every frame as read', async () => {
        const snapshot = await new PageState().capture(session!, {});
        expect(snapshot.unreadableFrames).toBe(0);
    });
});

/** The form's text input, told apart from the label that shares its accessible name. */
function fieldIn(nodes: SnapshotNode[]): SnapshotNode | undefined {
    return nodes.find(node => node.role === 'textbox' && node.name === FIELD_LABEL);
}

/**
 * Evaluates an expression with `w` bound to the innermost frame's window, which the page can reach
 * because every frame is same-origin. Until that frame exists the expression throws, which reads
 * as the fallback rather than as a failure.
 */
async function evaluateInInnerFrame<T>(active: CdpSession, expression: string, fallback: T): Promise<T> {
    const result = await active.send<{ result?: { value?: T } }>('Runtime.evaluate', {
        expression: `(() => { try { const w = window.frames[0].frames[0]; return (${expression}); } catch { return undefined; } })()`,
        returnByValue: true,
    });
    return result.result?.value ?? fallback;
}

async function innerFrameReady(active: CdpSession): Promise<boolean> {
    return evaluateInInnerFrame(
        active,
        "w.document.readyState === 'complete' && w.document.getElementById('addr') !== null",
        false
    );
}

async function innerScrollTop(active: CdpSession): Promise<number> {
    return evaluateInInnerFrame(active, 'w.scrollY', 0);
}

/**
 * Serves the shape a hosted form engine uses: a service page holding a same-origin renderer frame,
 * which writes a second frame of its own from script so its URL is never in any served HTML.
 */
function startFixtureServer(): Promise<Server> {
    const pages: Record<string, string> = {
        '/service': `<!doctype html><title>Service</title><h1>Start a service request</h1>
<iframe id="renderer" src="/renderer" width="800" height="600" style="border-width: 3px; padding: 7px"></iframe>
<div style="height: 1600px">Footer guidance, so the top page can scroll too.</div>`,
        '/renderer': `<!doctype html><title>Renderer</title><div id="mount"></div>
<script>
  const frame = document.createElement('iframe');
  frame.src = '/render?form=1';
  frame.width = 760;
  frame.height = 300;
  frame.style.borderWidth = '5px';
  frame.style.padding = '11px';
  document.getElementById('mount').appendChild(frame);
</script>`,
        '/render': `<!doctype html><title>Render</title><h2>Service request</h2>
<div style="height: 220px">Guidance text that pushes the field below the fold of its own frame.</div>
<form>
  <label for="addr">${FIELD_LABEL}</label><input id="addr" name="addr" type="text">
  <button id="send" type="button">Send request</button>
</form>
<div style="height: 900px">More guidance.</div>`,
    };

    const created = createServer((request, response) => {
        const body = pages[(request.url ?? '').split('?')[0]!];
        if (body === undefined) {
            response.writeHead(404);
            response.end('no such page');
            return;
        }
        response.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
        response.end(body);
    });
    return new Promise(resolve => created.listen(0, '127.0.0.1', () => resolve(created)));
}

// ABOUTME: Guards manifest.json, the file Claude Desktop reads to install this server as an MCPB
// ABOUTME: bundle, against drifting from the package it describes or the tools it actually registers.
import { existsSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import { TOOL_TABLE } from '../../src/core/profiles.js';
import { SERVER_VERSION } from '../../src/core/version.js';

const root = new URL('../../', import.meta.url);
const read = (name: string) => readFileSync(fileURLToPath(new URL(name, root)), 'utf8');

interface McpbManifest {
    manifest_version: string;
    name: string;
    display_name?: string;
    version: string;
    description: string;
    long_description?: string;
    author: { name: string; email?: string; url?: string };
    homepage?: string;
    documentation?: string;
    support?: string;
    icon?: string;
    license?: string;
    keywords?: string[];
    privacy_policies?: string[];
    repository?: { type: string; url: string };
    server: {
        type: string;
        entry_point: string;
        mcp_config: { command: string; args?: string[]; env?: Record<string, string> };
    };
    tools?: Array<{ name: string; description?: string }>;
    tools_generated?: boolean;
    user_config?: Record<
        string,
        { type: string; title: string; description: string; required?: boolean; sensitive?: boolean; default?: unknown }
    >;
    compatibility?: { platforms?: string[]; runtimes?: { node?: string } };
}

const bundle = JSON.parse(read('manifest.json')) as McpbManifest;
const pkg = JSON.parse(read('package.json')) as {
    version: string;
    license: string;
    description: string;
    engines: { node: string };
    repository: { url: string };
};

describe('the MCPB bundle manifest', () => {
    it('declares the manifest version the current mcpb toolchain validates against', () => {
        expect(bundle.manifest_version).toBe('0.4');
    });

    it('reports the same version as the package and the wire', () => {
        expect(bundle.version).toBe(pkg.version);
        expect(bundle.version).toBe(SERVER_VERSION);
    });

    it('is MIT licensed, which the directory requires', () => {
        expect(bundle.license).toBe('MIT');
        expect(bundle.license).toBe(pkg.license);
    });

    it('names an author reachable on GitHub, as the submission form requires', () => {
        expect(bundle.author.name).toBeTruthy();
        expect(bundle.author.url).toMatch(/^https:\/\/github\.com\/[\w-]+$/);
        expect(bundle.author.email).toContain('@');
    });

    it('links a privacy policy, whose absence is an immediate rejection', () => {
        expect(bundle.privacy_policies?.length).toBeGreaterThan(0);
        for (const url of bundle.privacy_policies ?? []) expect(url).toMatch(/^https:\/\//);
    });

    it('links the same privacy policy the README does', () => {
        // Review reads both. Two URLs that disagree is worse than one, and this is the pair most
        // likely to drift, since the policy lives on a site this repository does not control.
        const readme = read('README.md');
        for (const url of bundle.privacy_policies ?? []) {
            expect(readme, `the README never links ${url}`).toContain(url);
        }
    });

    it('points support and documentation somewhere a user can actually reach', () => {
        expect(bundle.support).toMatch(/^https:\/\//);
        expect(bundle.documentation).toMatch(/^https:\/\//);
        expect(bundle.repository?.url).toContain('steel-dev/steel-mcp-server');
    });
});

describe('the manifest launch configuration', () => {
    it('launches the built stdio entrypoint through Node', () => {
        expect(bundle.server.type).toBe('node');
        expect(bundle.server.entry_point).toBe('dist/stdio.js');
        expect(bundle.server.mcp_config.command).toBe('node');
    });

    it('resolves the entrypoint relative to the installed bundle rather than a developer checkout', () => {
        // An absolute path baked at author time points at a directory that does not exist on the
        // user's machine. ${__dirname} is what the host substitutes for the unpacked location.
        // biome-ignore lint/suspicious/noTemplateCurlyInString: an MCPB host placeholder, expanded at install time rather than by JS
        expect(bundle.server.mcp_config.args).toEqual(['${__dirname}/dist/stdio.js']);
    });

    it('takes the API key from user config, so Desktop prompts instead of shipping a placeholder', () => {
        const key = bundle.user_config?.steel_api_key;
        expect(key?.type).toBe('string');
        expect(key?.required).toBe(true);
        expect(key?.sensitive, 'the API key would be stored and displayed in the clear').toBe(true);
        // biome-ignore lint/suspicious/noTemplateCurlyInString: an MCPB host placeholder, expanded at install time rather than by JS
        expect(bundle.server.mcp_config.env?.STEEL_API_KEY).toBe('${user_config.steel_api_key}');
    });

    it('never hardcodes a credential in the manifest', () => {
        expect(read('manifest.json')).not.toMatch(/ste-[A-Za-z0-9]/);
    });

    it('declares the runtime the package requires', () => {
        expect(bundle.compatibility?.runtimes?.node).toBe(pkg.engines.node);
    });

    it('declares the platforms Claude for desktop runs on', () => {
        expect(bundle.compatibility?.platforms).toEqual(['darwin', 'win32']);
    });

    it('ships the icon it names', () => {
        expect(bundle.icon).toBeTruthy();
        expect(existsSync(fileURLToPath(new URL(bundle.icon as string, root)))).toBe(true);
    });
});

describe('the pack script', () => {
    const script = read('scripts/pack-mcpb.sh');

    it('stages every path the manifest and the launch config name', () => {
        for (const path of ['dist', 'manifest.json', 'LICENSE']) {
            expect(script, `the staging tree never copies ${path}`).toContain(path);
        }
    });

    it('stages the icon the manifest names rather than all of assets/', () => {
        // assets/ holds demo recordings — 75MB the bundle has no use for and every user would pay to
        // download. Reading the path from the manifest is also what keeps the two from drifting.
        expect(script).not.toMatch(/cp -R "\$ROOT\/assets"/);
        expect(script).toContain("require('$ROOT/manifest.json').icon");
    });

    it('installs without dev or optional dependencies', () => {
        expect(script).toContain('--omit=dev');
        expect(script).toContain('--omit=optional');
    });

    it('narrows the staged package.json before installing, rather than deleting trees afterwards', () => {
        // Deleting an installed directory leaves its dependencies behind: removing ioredis that way
        // still ships redis-parser, denque and four more. Narrowing first means npm never fetches them.
        expect(script).toContain('stage-mcpb-package.mjs');
        expect(script.indexOf('stage-mcpb-package.mjs')).toBeLessThan(script.indexOf('npm --prefix "$STAGE" install'));
    });

    it('keeps exactly the runtime dependencies the entrypoint reaches', () => {
        // The same set packaging.test.ts derives by walking the import graph from stdio.ts. If that
        // test's list changes and this one does not, the bundle is missing a package or carrying dead weight.
        const staging = read('scripts/stage-mcpb-package.mjs');
        const declared = /const RUNTIME_DEPENDENCIES = \[([^\]]+)\]/.exec(staging)?.[1] ?? '';
        expect([...declared.matchAll(/'([^']+)'/g)].map(match => match[1])).toEqual([
            '@modelcontextprotocol/server',
            '@opentelemetry/api',
            'safe-regex2',
            'ws',
            'zod',
        ]);
    });

    it('proves the staged server runs before packing it', () => {
        expect(script).toContain('verify-mcpb-stage.mjs');
        expect(script.indexOf('verify-mcpb-stage.mjs')).toBeLessThan(script.indexOf('$MCPB pack'));
    });

    it('validates the staged manifest rather than only the source one', () => {
        expect(script).toContain('validate "$STAGE/manifest.json"');
    });

    it('runs in CI, so a bundle that stops building fails a pull request', () => {
        expect(read('.github/workflows/ci.yml')).toContain('npm run pack:mcpb');
    });
});

describe('the manifest tool list', () => {
    it('lists exactly the tools the server registers, in the same order', () => {
        // TOOL_TABLE is the single source tools/list is built from, so matching it is matching the
        // wire. A manifest promising a tool that does not exist fails compatibility review.
        expect(bundle.tools?.map(tool => tool.name)).toEqual(TOOL_TABLE.map(tool => tool.name));
    });

    it('describes every tool it lists', () => {
        for (const tool of bundle.tools ?? []) {
            expect(tool.description, `${tool.name} has no description`).toBeTruthy();
        }
    });

    it('does not claim the list was generated by a host', () => {
        // tools_generated true tells a host these were discovered rather than authored, which would
        // excuse the list from matching. It is authored here, and tested against TOOL_TABLE.
        expect(bundle.tools_generated ?? false).toBe(false);
    });
});

// ABOUTME: Runs the MCP-App session viewer in a real headless Chrome behind a strict fake host and a
// ABOUTME: fake CDP endpoint, so its bridge order, painting, phases and teardown are executed, not read.
import { afterAll, afterEach, beforeAll, describe, expect, it } from 'vitest';
import { SESSION_VIEWER_IDLE_AFTER_MS, SESSION_VIEWER_LIVE_VIEW_TOOL } from '../../src/core/apps/session-viewer.js';
import { type FakeCdpOptions, FakeCdpServer, findOpenssl, frameMetadata } from '../helpers/fake-cdp-server.js';
import { announceMissing, findChrome, HeadlessChrome, until } from '../helpers/headless-chrome.js';
import { type FakeHostOptions, FakeMcpAppHost, type HostedViewer } from '../helpers/mcp-app-host.js';

const chromePath = findChrome();
const openssl = findOpenssl();
const missing = [chromePath === null ? 'Google Chrome' : null, openssl === null ? 'openssl' : null].filter(
    (name): name is string => name !== null
);
const available = missing.length === 0;
announceMissing('the session viewer browser suite', missing);

const SESSION_ID = 'sess-7f3a91c2b4d5';
const MAGENTA: [number, number, number] = [255, 0, 255];
const CYAN: [number, number, number] = [0, 255, 255];
const JPEG_WIDTH = 64;
const JPEG_HEIGHT = 40;
// The one expensive hook owns a 90s launch, a 20s WebSocket handshake and four 20s CDP commands.
// Its bound is scoped here so a broken cleanup hook still fails at the ordinary 60s project limit.
const BROWSER_SETUP_TIMEOUT_MS = 220_000;

let chrome: HeadlessChrome | undefined;
let magentaJpeg: string;
let cyanJpeg: string;

/** Everything the running test opened, torn down newest first however the test ended. */
let openedByTest: Array<() => Promise<void>> = [];

beforeAll(async () => {
    if (!available) return;
    chrome = await HeadlessChrome.launch(chromePath!);
    magentaJpeg = await chrome.encodeJpeg('#ff00ff', JPEG_WIDTH, JPEG_HEIGHT);
    cyanJpeg = await chrome.encodeJpeg('#00ffff', JPEG_WIDTH, JPEG_HEIGHT);
}, BROWSER_SETUP_TIMEOUT_MS);

afterAll(async () => {
    // Guarded on the browser rather than on `available`, because a launch that threw leaves the
    // prerequisites present and the browser unset, and closing it then buries the real failure.
    if (chrome !== undefined) await chrome.close();
});

afterEach(async () => {
    // Taken before anything is awaited. Vitest does not cancel a hook it timed out, so one that
    // resumes later would otherwise still be holding the list and would tear down the resources of
    // whichever test is running by then, reporting the failure against the wrong test.
    const opened = openedByTest;
    openedByTest = [];
    while (opened.length > 0) await opened.pop()!();
});

async function startCdp(options: FakeCdpOptions = {}): Promise<FakeCdpServer> {
    const server = await FakeCdpServer.start(openssl!, options);
    openedByTest.push(() => server.stop());
    return server;
}

async function startHost(options: FakeHostOptions): Promise<FakeMcpAppHost> {
    const host = await FakeMcpAppHost.start(options);
    openedByTest.push(() => host.stop());
    return host;
}

/** The browser this run launched. A test only reaches it after `beforeAll` succeeded. */
function browser(): HeadlessChrome {
    if (chrome === undefined) throw new Error('The session viewer suite ran a test without a launched Chrome.');
    return chrome;
}

async function openViewer(host: FakeMcpAppHost): Promise<HostedViewer> {
    const viewer = await host.open(browser());
    openedByTest.push(() => viewer.page.close());
    return viewer;
}

/** JPEG colours come back through a lossy encoder, so a painted pixel is compared with a tolerance. */
function isColour(pixel: readonly number[], expected: readonly [number, number, number]): boolean {
    return expected.every((channel, index) => Math.abs((pixel[index] ?? -1) - channel) <= 24) && pixel[3] === 255;
}

interface Stage {
    cdp: FakeCdpServer;
    viewer: HostedViewer;
}

/**
 * The ordinary case: a host that hands out a working live view for a session it has pushed.
 *
 * Returns once the app has opened its socket, which is the last thing that happens without a frame.
 */
async function connected(
    overrides: { cdp?: FakeCdpOptions; host?: FakeHostOptions; expiresAt?: string | number } = {}
): Promise<Stage> {
    const cdp = await startCdp(overrides.cdp);
    const host = await startHost({
        liveView: {
            kind: 'ok',
            cdpUrl: cdp.url,
            viewport: { width: 1600, height: 1000 },
            expiresAt: overrides.expiresAt,
        },
        ...overrides.host,
    });
    const viewer = await openViewer(host);
    await viewer.pushToolResult({ session_id: SESSION_ID });
    await cdp.waitForConnection();
    return { cdp, viewer };
}

/** Drives the app all the way to a painted magenta frame and returns once the canvas shows it. */
async function painting(overrides: Parameters<typeof connected>[0] = {}): Promise<Stage> {
    const stage = await connected(overrides);
    await stage.cdp.waitFor('Page.startScreencast');
    stage.cdp.sendFrame(magentaJpeg);
    await until(
        'the first frame to reach the canvas',
        () => stage.viewer.canvas(),
        canvas => canvas.width === JPEG_WIDTH && isColour(canvas.centre, MAGENTA)
    );
    return stage;
}

describe.skipIf(!available)('the session viewer in a real browser', () => {
    describe('the host bridge', () => {
        it('handshakes then calls a tool, in that order and with nothing the host has to refuse', async () => {
            const { cdp, viewer } = await connected();
            const log = await viewer.log();

