            expect(await viewer.modeLabel()).toBe('Watching (read-only)');

            await viewer.page.clickAt(400, 250);
            await new Promise(resolve => setTimeout(resolve, 400));

            expect(cdp.methods.filter(method => method.startsWith('Input.'))).toEqual([]);
        });

        it('maps a canvas point into the live page, and a point outside it to nothing', async () => {
            const { cdp, viewer } = await connected();
            await cdp.waitFor('Page.startScreencast');

            expect(await viewer.mapPoint(400, 250), 'nothing is mappable before a frame arrives').toBe(null);

            cdp.sendFrame(magentaJpeg, frameMetadata({ scrollOffsetX: 100, scrollOffsetY: 200 }));
            await until(
                'a frame to give the mapping something to work from',
                () => viewer.mapPoint(400, 250),
                point => point !== null
            );

            const centre = (await viewer.mapPoint(400, 250)) as { viewportX: number; pageX: number; pageY: number };
            expect(centre.viewportX, 'the middle of the canvas is the middle of the 1024px page').toBeGreaterThan(430);
            expect(centre.viewportX).toBeLessThan(600);
            expect(centre.pageX, 'the document point adds the page scroll').toBe(centre.viewportX + 100);
            expect(await viewer.mapPoint(2, 2), 'the letterbox beside the frame is not in the page').toBe(null);
        });
    });

    describe('take-control: forwarding real input over CDP', () => {
        it('offers the toggle once attached, and switches its visible state when driven', async () => {
            const { viewer } = await painting();

            expect(await viewer.modeLabel(), 'read-only is the safe default').toBe('Watching (read-only)');

            await viewer.takeControl();
            expect(await viewer.driving()).toBe(true);
            expect(await viewer.modeLabel()).toBe('You are driving this browser');

            await viewer.handBack();
            expect(await viewer.driving()).toBe(false);
            expect(await viewer.modeLabel()).toBe('Watching (read-only)');
            expect(viewer.page.appExceptions).toEqual([]);
        });

        it('moves a user-picked local file directly into the remote file input without an MCP payload', async () => {
            const { cdp, viewer } = await painting();
            await viewer.takeControl();
            cdp.sendFileChooser(42);
            await until(
                'the trusted local file control to appear',
                () => viewer.fileControl(),
                shown => !shown.hidden
            );

            await viewer.selectLocalFile('cv.pdf', 'hello', 'application/pdf');
            const [install] = await cdp.waitFor('Runtime.callFunctionOn');
            expect(install!.params.objectId).toBe('remote-file-input-1');
            expect(install!.params.arguments).toEqual([
                { value: 'aGVsbG8=' },
                { value: 'cv.pdf' },
                { value: 'application/pdf' },
            ]);
            await until(
                'the local file control to close',
                () => viewer.fileControl(),
                shown => shown.hidden
            );

            const bridge = JSON.stringify((await viewer.log()).messages);
            expect(bridge).not.toContain('cv.pdf');
            expect(bridge).not.toContain('aGVsbG8=');
            expect(viewer.page.appExceptions).toEqual([]);
        });

        it('forwards a canvas click as a pressed and released mouse event with the mapped point', async () => {
            const { cdp, viewer } = await painting();
            await viewer.takeControl();

            const probe = await viewer.driveClick(0.5, 0.5);
            await cdp.waitFor('Input.dispatchMouseEvent', 2);

            const inputs = cdp.inputCommands;
            expect(inputs.map(cmd => cmd.params.type)).toEqual(['mousePressed', 'mouseReleased']);
            const pressed = inputs[0]!.params as {
                x: number;
                y: number;
                button: string;
                buttons: number;
                clickCount: number;
            };
            expect(probe, 'the centre of the canvas maps into the page').not.toBe(null);
            expect(pressed.x).toBe((probe as { viewportX: number }).viewportX);
            expect(pressed.y).toBe((probe as { viewportY: number }).viewportY);
            expect(pressed).toMatchObject({ button: 'left', buttons: 1, clickCount: 1 });
            expect(viewer.page.appExceptions).toEqual([]);
        });

        it('raises the click count for a double click', async () => {
            const { cdp, viewer } = await painting();
            await viewer.takeControl();

            await viewer.driveClick(0.5, 0.5, 2);
            const [pressed] = await cdp.waitFor('Input.dispatchMouseEvent');
            expect((pressed!.params as { clickCount: number }).clickCount).toBe(2);
        });

        it('forwards a wheel event as a mouseWheel carrying the deltas', async () => {
            const { cdp, viewer } = await painting();
            await viewer.takeControl();

            await viewer.driveWheel(0.5, 0.5, 3, 24);
            const [wheel] = await cdp.waitFor('Input.dispatchMouseEvent');
            expect(wheel!.params).toMatchObject({ type: 'mouseWheel', deltaX: 3, deltaY: 24 });
        });

        it('forwards a key as a keyDown dispatch, and inserts text only for a printable char', async () => {
            const { cdp, viewer } = await painting();
            await viewer.takeControl();

            await viewer.driveKey('keydown', 'a', 'KeyA');
            await cdp.waitFor('Input.dispatchKeyEvent');
            await cdp.waitFor('Input.insertText');

            const keyDown = cdp.inputCommands.find(cmd => cmd.method === 'Input.dispatchKeyEvent')!.params as Record<
                string,
                unknown
            >;
            expect(keyDown).toEqual({
                type: 'keyDown',
                key: 'a',
                code: 'KeyA',
                windowsVirtualKeyCode: 65,
                modifiers: 0,
            });
            expect(cdp.inputCommands.find(cmd => cmd.method === 'Input.insertText')!.params).toEqual({ text: 'a' });

            // Enter is a control key: a keyDown is forwarded, but no text is inserted.
            const before = cdp.inputCommands.length;
            await viewer.driveKey('keydown', 'Enter', 'Enter');
            await cdp.waitFor('Input.dispatchKeyEvent', 2);
            await new Promise(resolve => setTimeout(resolve, 150));

            expect(cdp.inputCommands.length, 'Enter added exactly one keyDown').toBe(before + 1);
            expect(cdp.inputCommands.at(-1)!.method).toBe('Input.dispatchKeyEvent');
            expect((cdp.inputCommands.at(-1)!.params as { windowsVirtualKeyCode: number }).windowsVirtualKeyCode).toBe(
                13
            );
            expect(
                cdp.inputCommands.filter(cmd => cmd.method === 'Input.insertText').length,
                'only the earlier a was inserted'
            ).toBe(1);
            expect(viewer.page.appExceptions).toEqual([]);
        });

        it('stops forwarding the moment control is handed back', async () => {
            const { cdp, viewer } = await painting();
            await viewer.takeControl();
            await viewer.driveClick(0.5, 0.5);
            await cdp.waitFor('Input.dispatchMouseEvent', 2);
            const forwardedWhileDriving = cdp.inputCommands.length;
            expect(forwardedWhileDriving).toBeGreaterThan(0);

            await viewer.handBack();
            await viewer.driveClick(0.5, 0.5);
            await new Promise(resolve => setTimeout(resolve, 200));

            expect(cdp.inputCommands.length, 'no further input after hand-back').toBe(forwardedWhileDriving);
            expect(viewer.page.appExceptions).toEqual([]);
        });

        it('forwards nothing for a click the canvas-to-page mapping rejects', async () => {
            const { cdp, viewer } = await painting();
            await viewer.takeControl();

            const probe = await viewer.driveLetterboxMouseDown();
            await new Promise(resolve => setTimeout(resolve, 200));

            expect(probe, 'the point is outside the live page').toBe(null);
            expect(cdp.inputCommands).toEqual([]);
            expect(viewer.page.appExceptions).toEqual([]);
        });

        it('keeps the drive-capable CDP address out of the document after a control session', async () => {
            const { cdp, viewer } = await painting();
            await viewer.takeControl();
            await viewer.driveClick(0.5, 0.5);
            await viewer.driveKey('keydown', 'a', 'KeyA');
            await cdp.waitFor('Input.dispatchMouseEvent');

            const html = await viewer.documentHtml();
            expect(html).not.toContain(cdp.token);
            expect(html).not.toContain('token=');
            expect(html).not.toMatch(/wss:\/\/127\.0\.0\.1/);
        });
    });
});

// ABOUTME: A strict fake MCP-Apps host: serves the session viewer in a sandboxed iframe, speaks the
// ABOUTME: postMessage bridge, records every message in order and refuses anything out of sequence.
import { createServer, type Server } from 'node:http';
import {
    SESSION_VIEWER_HTML,
    SESSION_VIEWER_LIVE_VIEW_TOOL,
    SESSION_VIEWER_READY_MESSAGE_TYPE,
} from '../../src/core/apps/session-viewer.js';
import type { BrowserPage, HeadlessChrome } from './headless-chrome.js';

/** What the fake host makes `tools/call` for the live-view tool answer. */
export type LiveViewAnswer =
    | { kind: 'ok'; cdpUrl: string; viewport?: { width: number; height: number }; expiresAt?: string | number }
    /** A tool that ran and reported failure: `isError` with text, not a JSON-RPC error. */
    | { kind: 'tool-error'; message: string }
    /** The host itself refusing the call. */
    | { kind: 'rpc-error'; message: string }
    /** A reply with no `structuredContent` at all. */
    | { kind: 'no-details' }
    /** No answer ever, to run the app's own call timeout. */
    | { kind: 'silent' };

export interface FakeHostOptions {
    /** The `ui/initialize` protocol versions this host speaks; it declines every other one. */
    acceptedProtocolVersions?: readonly string[];
    /**
     * How long the host sits on a successful `ui/initialize` reply.
     *
     * A slow host is what makes the app's own ordering rule testable: a session pushed during the
     * delay must still not produce a `tools/call` before the initialized notification.
     */
    initializeDelayMs?: number;
    /**
     * An extra `content-security-policy` response header for the app document.
     *
     * A real MCP host narrows the app's `connect-src` to the origins the resource declared, so this
     * is how a test makes the host refuse the socket the app wants to open.
     */
    appCsp?: string;
    liveView?: LiveViewAnswer;
    /**
     * Whether `ui/request-display-mode` is honoured.
     *
     * A host answers with the mode it actually set, so `false` here models the host that keeps the
     * view inline whatever it is asked for — which an app must not present as a working control.
     */
    grantsDisplayMode?: boolean;
}

/** One JSON-RPC request or notification the app posted to its parent. */
export interface HostMessage {
    method: string;
    id?: number | string;
    params?: Record<string, unknown>;
}

/** One JSON-RPC response the app posted back for a request the host made. */
export interface HostResponse {
    id: number | string;
    result?: unknown;
    error?: unknown;
}

/** Everything the host page recorded, read out of the browser in one round trip. */
export interface HostLog {
    messages: HostMessage[];
    responses: HostResponse[];
    /** Requests the host refused because the app broke the bridge contract. */
    violations: string[];
    /** True once the app posted its plain ready echo. */
    ready: boolean;
    initialized: boolean;
}

/** What the app is showing, as a user would read it off the screen. */
export interface ViewerScreen {
    headline: string;
    note: string;
    badge: string;
    veilHidden: boolean;
    badgeHidden: boolean;
    spinHidden: boolean;
}

/** What is on the canvas: its pixel size and the colour at its centre. */
export interface ViewerCanvas {
    width: number;
    height: number;
    centre: [number, number, number, number];
}

const DEFAULT_VERSIONS = ['2026-01-26', '2025-11-25', '2025-06-18'] as const;

function hostDocument(options: FakeHostOptions): string {
    const config = {
        liveViewTool: SESSION_VIEWER_LIVE_VIEW_TOOL,
        readyMessage: SESSION_VIEWER_READY_MESSAGE_TYPE,
        acceptedProtocolVersions: options.acceptedProtocolVersions ?? DEFAULT_VERSIONS,
        initializeDelayMs: options.initializeDelayMs ?? 0,
        liveView: options.liveView ?? { kind: 'silent' },
        grantsDisplayMode: options.grantsDisplayMode ?? true,
    };
    // Kept to plain ES5 and one listener so the sequence it enforces is readable at a glance.
    return `<!doctype html>
<html lang="en">
<head><meta charset="utf-8"><title>Fake MCP Apps host</title>
<style>html,body{margin:0;height:100%}iframe{display:block;width:800px;height:500px;border:0}</style></head>
<body>
<iframe id="app" src="/app" sandbox="allow-scripts"></iframe>
<script>
'use strict';
var CONFIG = ${JSON.stringify(config)};
var log = { messages: [], responses: [], violations: [], ready: false, initialized: false };
window.__host = log;

function app(){ return document.getElementById('app').contentWindow; }
function post(message){ app().postMessage(message, '*'); }
function reply(id, result){ post({ jsonrpc: '2.0', id: id, result: result }); }
/** A legitimate refusal: the app asked for something this host does not offer. */
function decline(id, message){ post({ jsonrpc: '2.0', id: id, error: { code: -32601, message: message } }); }
/** The app broke the bridge contract. Recorded, so a test never has to infer it from ordering. */
function refuse(id, message){ log.violations.push(message); post({ jsonrpc: '2.0', id: id, error: { code: -32600, message: message } }); }

function answerLiveView(id, args){
  var action = args && args.action;
  if (action === 'acquire' || action === 'renew') {
    var token = action === 'renew' ? args.control_token : '[REDACTED]';
    reply(id, { content: [{ type: 'text', text: 'control ready' }], structuredContent: {
      session_id: args.session_id,
      control: { state: 'human', token: token, lease_expires_at: new Date(Date.now() + 60000).toISOString() }
    } });
    return;
  }
  if (action === 'release') {
    reply(id, { content: [{ type: 'text', text: 'control returned' }], structuredContent: {
      session_id: args.session_id, control: { state: 'agent' }
    } });
    return;
  }
  var answer = CONFIG.liveView;
  if (answer.kind === 'silent') return;
  if (answer.kind === 'rpc-error') { decline(id, answer.message); return; }
  if (answer.kind === 'tool-error') { reply(id, { isError: true, content: [{ type: 'text', text: answer.message }] }); return; }
  if (answer.kind === 'no-details') { reply(id, { content: [{ type: 'text', text: 'the live view is not available' }] }); return; }
  var structured = { session_id: (args && args.session_id) || 'sess-resolved-by-host', cdp_url: answer.cdpUrl };
  if (answer.viewport) structured.viewport = answer.viewport;
  if (answer.expiresAt !== undefined) structured.expires_at = answer.expiresAt;
  reply(id, { content: [{ type: 'text', text: 'live view ready' }], structuredContent: structured });
}

window.addEventListener('message', function (event) {
  var message = event.data;
  if (message && message.type === CONFIG.readyMessage) { log.ready = true; return; }
  if (!message || message.jsonrpc !== '2.0') return;
  if (message.method === undefined) {
    log.responses.push({ id: message.id, result: message.result, error: message.error });
    return;
  }
  log.messages.push({ method: message.method, id: message.id, params: message.params });

  if (message.method === 'ui/initialize') {
    if (log.initialized) { refuse(message.id, 'ui/initialize after the app already said it was initialized'); return; }
    var params = message.params || {};
    if (typeof params.protocolVersion !== 'string' || !params.appCapabilities) {
      refuse(message.id, 'ui/initialize without both a protocolVersion and appCapabilities');
      return;
    }
    if (CONFIG.acceptedProtocolVersions.indexOf(params.protocolVersion) === -1) {
      decline(message.id, 'this host does not speak ' + params.protocolVersion);
      return;
    }
    var accepted = {
      protocolVersion: params.protocolVersion,
      hostCapabilities: { serverTools: {} },
      hostInfo: { name: 'fake-mcp-app-host', version: '1.0.0' },
      hostContext: { theme: 'dark', displayMode: 'inline' }
    };
    var id = message.id;
    if (CONFIG.initializeDelayMs > 0) setTimeout(function(){ reply(id, accepted); }, CONFIG.initializeDelayMs);
    else reply(id, accepted);
    return;
  }

  if (message.method === 'ui/notifications/initialized') {
    if (log.initialized) log.violations.push('a second ui/notifications/initialized');
    log.initialized = true;
    return;
  }

  // Nothing but the handshake itself may precede the initialized notification.
  if (message.method.indexOf('ui/') === 0 && message.method !== 'ui/initialize' && !log.initialized) {
    log.violations.push(message.method + ' before ui/notifications/initialized');
  }

  if (message.method === 'ui/request-display-mode') {
    var wanted = message.params && message.params.mode;
    // A host answers with the mode it actually set, which need not be the one asked for.
    reply(message.id, { mode: CONFIG.grantsDisplayMode ? wanted : 'inline' });
    return;
  }

  if (message.method === 'tools/call') {
    if (!log.initialized) { refuse(message.id, 'tools/call before ui/notifications/initialized'); return; }
    var name = message.params && message.params.name;
    if (name !== CONFIG.liveViewTool) { refuse(message.id, 'tools/call for an unexpected tool: ' + name); return; }
    answerLiveView(message.id, (message.params && message.params.arguments) || {});
    return;
  }

  if (message.id !== undefined) refuse(message.id, 'an unexpected request: ' + message.method);
});

/** The push a host makes when a tool the conversation ran produced a result the app may use. */
window.__pushToolResult = function (structuredContent) {
  post({ jsonrpc: '2.0', method: 'ui/notifications/tool-result', params: {
    content: [{ type: 'text', text: 'a session is open' }],
    structuredContent: structuredContent
  } });
};

/** What a host sends just before it removes the app from the conversation. */
window.__requestTeardown = function (id) {
  post({ jsonrpc: '2.0', id: id, method: 'ui/resource-teardown', params: {} });
};
</script>
</body>
</html>`;
}

/**
 * The fake host, serving its own page and the app over loopback HTTP.
 *
 * `127.0.0.1` is a secure context, so plain HTTP is enough for the documents; only the CDP endpoint
 * has to be TLS, because `wss:` is the only scheme the app will open.
 */
export class FakeMcpAppHost {
    private constructor(
        private readonly server: Server,
        /** The host page to load; the app frame inside it comes up on its own. */
        readonly url: string
    ) {}

    static async start(options: FakeHostOptions = {}): Promise<FakeMcpAppHost> {
        const document = hostDocument(options);
        const server = createServer((request, response) => {
            if (request.url === '/host') {
                response.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
                response.end(document);
                return;
            }
            if (request.url === '/app') {
                const headers: Record<string, string> = { 'content-type': 'text/html; charset=utf-8' };
                if (options.appCsp !== undefined) headers['content-security-policy'] = options.appCsp;
                response.writeHead(200, headers);
                response.end(SESSION_VIEWER_HTML);
                return;
            }
            response.writeHead(404).end();
        });
        await new Promise<void>(resolve => server.listen(0, '127.0.0.1', resolve));
        const address = server.address();
        if (address === null || typeof address === 'string') throw new Error('the fake host has no port');
        return new FakeMcpAppHost(server, `http://127.0.0.1:${address.port}/host`);
    }

    /** Loads the host page in a fresh tab and returns a handle on the app running inside it. */
    async open(chrome: HeadlessChrome): Promise<HostedViewer> {
        return new HostedViewer(await chrome.openPage(this.url));
    }

    async stop(): Promise<void> {
        // `close` stops new connections and then waits for the open ones, and a browser keeps its
        // connection alive after the page using it is gone. Waiting for the browser to give it up is
        // waiting on a keep-alive timeout, so the sockets are dropped rather than waited for.
        const closed = new Promise<void>(resolve => this.server.close(() => resolve()));
        this.server.closeAllConnections();
        await closed;
    }
}

/** A running session viewer: what the host saw, what the app shows, and how to nudge either. */
export class HostedViewer {
    constructor(readonly page: BrowserPage) {}

    /** Everything the host page recorded so far. */
    log(): Promise<HostLog> {
        return this.page.evalInHost<HostLog>('JSON.parse(JSON.stringify(window.__host))');
    }

    /** The bridge methods the app sent, in order. */
    async bridgeMethods(): Promise<string[]> {
        return (await this.log()).messages.map(message => message.method);
    }

    /** Pushes a tool result the way a host does when the conversation ran a tool. */
    async pushToolResult(structuredContent: Record<string, unknown>): Promise<void> {
        await this.page.evalInHost(`window.__pushToolResult(${JSON.stringify(structuredContent)})`);
    }

    /** Asks the app to tear down, as a host does before it removes the view. */
    async requestTeardown(id = 900): Promise<void> {
        await this.page.evalInHost(`window.__requestTeardown(${JSON.stringify(id)})`);
    }

    /** What the app is showing right now. */
    screen(): Promise<ViewerScreen> {
        return this.page.evalInApp<ViewerScreen>(
            `(function(){` +
                `var veil = document.getElementById('veil');` +
                `var badge = document.getElementById('badge');` +
                `return {` +
                `headline: document.getElementById('head').textContent,` +
                `note: document.getElementById('note').textContent,` +
                `badge: badge.textContent,` +
                `veilHidden: veil.hidden, badgeHidden: badge.hidden,` +
                `spinHidden: document.getElementById('spin').hidden` +
                `};})()`
        );
    }

    /** The canvas size and the colour at its centre, which is blank until a frame is drawn. */
    canvas(): Promise<ViewerCanvas> {
        return this.page.evalInApp<ViewerCanvas>(
            `(function(){` +
                `var canvas = document.getElementById('screen');` +
                `var pixel = canvas.getContext('2d').getImageData(Math.floor(canvas.width / 2), Math.floor(canvas.height / 2), 1, 1).data;` +
                `return { width: canvas.width, height: canvas.height, centre: [pixel[0], pixel[1], pixel[2], pixel[3]] };` +
                `})()`
        );
    }

    /** The aspect ratio the app is holding the stage at. */
    aspectRatio(): Promise<string> {
        return this.page.evalInApp<string>(`document.getElementById('stage').style.getPropertyValue('--ar')`);
    }

    /** The app's whole rendered document, for checking what did *not* end up in it. */
    documentHtml(): Promise<string> {
        return this.page.evalInApp<string>('document.documentElement.outerHTML');
    }

    /** Runs the app's own canvas-to-page mapping against a point in the app frame. */
    mapPoint(clientX: number, clientY: number): Promise<unknown> {
        return this.page.evalInApp<unknown>(
            `window.steelSessionViewer.pointFromCanvasEvent({ clientX: ${clientX}, clientY: ${clientY} })`
        );
    }

    /** Clicks the real full-screen control, the path a human takes. */
    clickExpand(): Promise<void> {
        return this.page.evalInApp("document.getElementById('expand').click()");
    }

    /** What the full-screen control is showing: its label, and whether it is offered at all. */
    expandControl(): Promise<{ label: string; hidden: boolean }> {
        return this.page.evalInApp(
            `(function(){var b=document.getElementById('expand');` +
                `return { label: b.textContent, hidden: b.hidden };})()`
        );
    }

    /** Turns take-control on by clicking the real toggle, the path a human takes. */
    async takeControl(): Promise<void> {
        await this.page.evalInApp(
            "var b=document.getElementById('control'); if(b.getAttribute('aria-pressed')!=='true') b.click();"
        );
        for (let attempt = 0; attempt < 100; attempt++) {
            if (await this.driving()) return;
            await new Promise(resolve => setTimeout(resolve, 10));
        }
        throw new Error('the viewer did not acquire human control');
    }

    /** Turns take-control off by clicking the real toggle again. */
    async handBack(): Promise<void> {
        await this.page.evalInApp(
            "var b=document.getElementById('control'); if(b.getAttribute('aria-pressed')==='true') b.click();"
        );
        for (let attempt = 0; attempt < 100; attempt++) {
            if (!(await this.driving())) return;
            await new Promise(resolve => setTimeout(resolve, 10));
        }
        throw new Error('the viewer did not return control');
    }

    /** Whether the app is currently forwarding input, read off the toggle's pressed state. */
    driving(): Promise<boolean> {
        return this.page.evalInApp<boolean>("document.getElementById('control').getAttribute('aria-pressed')==='true'");
    }

    /** The visible mode label ("Watching (read-only)" / "You are driving this browser"). */
    modeLabel(): Promise<string> {
        return this.page.evalInApp<string>("document.getElementById('mode').textContent");
    }

    /** Whether a remote file input has made the trusted local-picker control available. */
    fileControl(): Promise<{ hidden: boolean; disabled: boolean }> {
        return this.page.evalInApp(
            `(function(){var b=document.getElementById('attach');return {hidden:b.hidden,disabled:b.disabled};})()`
        );
    }

    /** Supplies a local file to the viewer as if the native picker returned it, without disk fixtures. */
    selectLocalFile(name: string, text: string, type: string): Promise<void> {
        return this.page.evalInApp(
            `(function(){window.confirm=function(){return true};var input=document.getElementById('local-file');` +
                `var transfer=new DataTransfer();transfer.items.add(new File([${JSON.stringify(text)}],` +
                `${JSON.stringify(name)},{type:${JSON.stringify(type)}}));input.files=transfer.files;` +
                `input.dispatchEvent(new Event('change',{bubbles:true}));})()`
        );
    }

    /** Dispatches a synthetic key event on the canvas the way a focused canvas would receive it. */
    driveKey(
        type: 'keydown' | 'keyup',
        key: string,
        code: string,
        mods: { shift?: boolean; ctrl?: boolean; alt?: boolean; meta?: boolean } = {}
    ): Promise<void> {
        const init = JSON.stringify({
            bubbles: true,
            cancelable: true,
            key,
            code,
            shiftKey: !!mods.shift,
            ctrlKey: !!mods.ctrl,
            altKey: !!mods.alt,
            metaKey: !!mods.meta,
        });
        return this.page.evalInApp(
            `document.getElementById('screen').dispatchEvent(new KeyboardEvent(${JSON.stringify(type)}, ${init}))`
        );
    }

    /** Dispatches a synthetic wheel event at a fractional position inside the canvas. */
    driveWheel(fracX: number, fracY: number, deltaX: number, deltaY: number): Promise<void> {
        return this.page.evalInApp(
            `(function(){var r=document.getElementById('screen').getBoundingClientRect();` +
                `document.getElementById('screen').dispatchEvent(new WheelEvent('wheel',` +
                `{bubbles:true,cancelable:true,deltaX:${deltaX},deltaY:${deltaY},` +
                `clientX:r.left+r.width*${fracX},clientY:r.top+r.height*${fracY}}));})()`
        );
    }

    /**
     * Dispatches a mousedown/mouseup pair on the canvas at a fractional position, and returns the
     * viewport point the app mapped that click to (or null when the mapping rejected it).
     */
    driveClick(fracX: number, fracY: number, detail = 1): Promise<{ viewportX: number; viewportY: number } | null> {
        return this.page.evalInApp(
            `(function(){var c=document.getElementById('screen');var r=c.getBoundingClientRect();` +
                // Integer client coords: Chrome snaps a MouseEvent's clientX/Y to a long, so rounding
                // here makes the probe the handler reads agree with the point the dispatch carries.
                `var x=Math.round(r.left+r.width*${fracX});var y=Math.round(r.top+r.height*${fracY});` +
                `var probe=window.steelSessionViewer.pointFromCanvasEvent({clientX:x,clientY:y});` +
                `c.dispatchEvent(new MouseEvent('mousedown',{bubbles:true,cancelable:true,` +
                `button:0,buttons:1,detail:${detail},clientX:x,clientY:y}));` +
                `c.dispatchEvent(new MouseEvent('mouseup',{bubbles:true,cancelable:true,` +
                `button:0,buttons:0,detail:${detail},clientX:x,clientY:y}));return probe;})()`
        );
    }

    /**
     * Dispatches a mousedown on the canvas at a point its own mapping rejects, and returns that point.
     *
     * The point sits just outside the canvas element, so a real letterbox or out-of-bounds click is
     * reproduced: the listener runs (the event is dispatched on the canvas) but no command is built.
     */
    driveLetterboxMouseDown(): Promise<unknown> {
        return this.page.evalInApp<unknown>(
            `(function(){var c=document.getElementById('screen');var r=c.getBoundingClientRect();` +
                `var x=r.left-5;var y=r.top+r.height/2;` +
                `var probe=window.steelSessionViewer.pointFromCanvasEvent({clientX:x,clientY:y});` +
                `c.dispatchEvent(new MouseEvent('mousedown',{bubbles:true,cancelable:true,` +
                `button:0,buttons:1,detail:1,clientX:x,clientY:y}));return probe;})()`
        );
    }
}

// ABOUTME: An in-memory OpenTelemetry pipeline for tests: a real tracer whose finished spans are
// ABOUTME: readable, plus the async-context manager span nesting needs to work across awaits.
import { context, type Tracer } from '@opentelemetry/api';
import { AsyncLocalStorageContextManager } from '@opentelemetry/context-async-hooks';
import {
    BasicTracerProvider,
    InMemorySpanExporter,
    type ReadableSpan,
    SimpleSpanProcessor,
} from '@opentelemetry/sdk-trace-base';

/** A tracing starter that records how it was called instead of loading the real OTLP SDK. */
export function fakeTracingStarter(options: { failWith?: Error } = {}) {
    const started: Array<{ serviceName: string }> = [];
    let shutdowns = 0;
    return {
        started,
        shutdownCount: () => shutdowns,
        start: async (config: { serviceName: string }) => {
            if (options.failWith) throw options.failWith;
            started.push(config);
            return {
                shutdown: async () => {
                    shutdowns += 1;
                },
            };
        },
    };
}

export interface TracingHarness {
    /** Pass this as `ServerDeps.tracer`, or to a Steel client, to record its spans. */
    tracer: Tracer;
    /** Finished spans in the order they ended. */
    spans(): ReadableSpan[];
    /** The one span with this name, failing loudly when there is not exactly one. */
    span(name: string): ReadableSpan;
    reset(): void;
    shutdown(): Promise<void>;
}

/**
 * Registered once per worker rather than per harness.
 *
 * A second `setGlobalContextManager` call is refused by the API with a diagnostic, which would both
 * leave a stray message in the test output and silently keep the first manager.
 */
let contextManager: AsyncLocalStorageContextManager | undefined;

/** Builds a recording tracer whose spans are inspectable, with async context propagation live. */
export function tracingHarness(): TracingHarness {
    if (!contextManager) {
        contextManager = new AsyncLocalStorageContextManager().enable();
        context.setGlobalContextManager(contextManager);
    }

    const exporter = new InMemorySpanExporter();
    const provider = new BasicTracerProvider({ spanProcessors: [new SimpleSpanProcessor(exporter)] });

    return {
        tracer: provider.getTracer('test'),
        spans: () => exporter.getFinishedSpans(),
        span: (name: string) => {
            const matches = exporter.getFinishedSpans().filter(span => span.name === name);
            if (matches.length !== 1) {
                const names = exporter
                    .getFinishedSpans()
                    .map(span => span.name)
                    .join(', ');
                throw new Error(`Expected exactly one span named "${name}", found ${matches.length} in [${names}]`);
            }
            return matches[0]!;
        },
        reset: () => exporter.reset(),
        shutdown: async () => {
            await provider.shutdown();
        },
    };
}

// ABOUTME: Integration tests for the CDP client against a real WebSocket server speaking minimal
// ABOUTME: CDP, covering the abort contract: cancel the handshake, never close a live connection.
import type { AddressInfo } from 'node:net';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { WebSocketServer } from 'ws';
import { CdpConnection } from '../../src/core/steel/cdp.js';

interface Harness {
    url: string;
    close(): Promise<void>;
    /** Methods the fake browser refuses to answer, so a caller's timeout path can be exercised. */
    silent: Set<string>;
}

async function startFakeBrowser(): Promise<Harness> {
    const server = new WebSocketServer({ host: '127.0.0.1', port: 0 });
    const silent = new Set<string>();

    server.on('connection', socket => {
        socket.on('message', raw => {
            const message = JSON.parse(String(raw)) as { id: number; method: string; sessionId?: string };
            if (silent.has(message.method)) return;

            const reply = (result: unknown) =>
                socket.send(JSON.stringify({ id: message.id, result, sessionId: message.sessionId }));

            switch (message.method) {
                case 'Target.getTargets':
                    reply({
                        targetInfos: [
                            { targetId: 'bg', type: 'background_page' },
                            { targetId: 'page-1', type: 'page' },
                        ],
                    });
                    break;
                case 'Target.attachToTarget':
                    reply({ sessionId: 'attached-1' });
                    break;
                case 'Nonexistent.method':
                    socket.send(
                        JSON.stringify({ id: message.id, error: { code: -32601, message: 'method not found' } })
                    );
                    break;
                default:
                    reply({ ok: true });
            }
        });
    });

    await new Promise<void>(resolve => server.once('listening', resolve));
    const { port } = server.address() as AddressInfo;

    return {
        url: `ws://127.0.0.1:${port}/`,
        silent,
        close: () =>
            new Promise<void>(resolve => {
                for (const client of server.clients) client.terminate();
                server.close(() => resolve());
            }),
    };
}

let harness: Harness;

beforeEach(async () => {
    harness = await startFakeBrowser();
});

afterEach(async () => {
    await harness.close();
});

describe('CdpConnection.connect', () => {
    it('connects, attaches to the page target and round-trips a command', async () => {
        const connection = await CdpConnection.connect(harness.url);
        const session = await connection.attachToPage();
        await expect(session.send('Page.enable')).resolves.toEqual({ ok: true });
        await connection.close();
    });

    it('reports a protocol error from the browser as a tool error naming the method', async () => {
        const connection = await CdpConnection.connect(harness.url);
        await expect(connection.send('Nonexistent.method')).rejects.toThrow(/Nonexistent\.method.*method not found/);
        await connection.close();
    });

    // Both abort paths reach terminate() on a socket that never opened. Vitest fails the run on an
    // uncaught exception, so these also pin that terminate() never escapes as one.
    it('rejects when the signal is already aborted before the connection starts', async () => {
        const controller = new AbortController();
        controller.abort();
        await expect(CdpConnection.connect(harness.url, controller.signal)).rejects.toThrow(/cancelled/i);
    });

    it('rejects when the signal aborts during the handshake', async () => {
        const controller = new AbortController();
        const connecting = CdpConnection.connect(harness.url, controller.signal);
        controller.abort();
        await expect(connecting).rejects.toThrow(/cancelled/i);
    });

    it('reports an unreachable browser rather than hanging', async () => {
        await expect(CdpConnection.connect('ws://127.0.0.1:1/')).rejects.toThrow(/could not open/i);
    });
});

describe('the abort contract after the handshake', () => {
    it('leaves the connection usable when the request that opened it is cancelled', async () => {
        const controller = new AbortController();
        const connection = await CdpConnection.connect(harness.url, controller.signal);

        // The signal belongs to one tool call. The connection is pooled for the whole session, so
        // cancelling that call must not brick the handle while Steel keeps billing for the browser.
        controller.abort();
        await new Promise(resolve => setTimeout(resolve, 20));

        expect(connection.isClosed).toBe(false);
        await expect(connection.send('Page.enable')).resolves.toEqual({ ok: true });
        await connection.close();
    });

    it('reports itself closed only once it really is', async () => {
        const connection = await CdpConnection.connect(harness.url);
        expect(connection.isClosed).toBe(false);
        await connection.close();
        expect(connection.isClosed).toBe(true);
    });

    it('rejects further commands after close, naming the recovery', async () => {
        const connection = await CdpConnection.connect(harness.url);
        await connection.close();
        await expect(connection.send('Page.enable')).rejects.toThrow(/create a new session/i);
    });

    it('fails in-flight commands when the browser goes away', async () => {
        harness.silent.add('Page.enable');
        const connection = await CdpConnection.connect(harness.url);
        const pending = connection.send('Page.enable');
        await harness.close();
        await expect(pending).rejects.toThrow(/connection (closed|failed)/i);
        expect(connection.isClosed).toBe(true);
    });
});

// ABOUTME: Integration tests for tool-call tracing driven through a real MCP client: one span per
// ABOUTME: call, parent linkage from the caller's _meta, and no credential anywhere in a span.
import { Client } from '@modelcontextprotocol/client';
import { InMemoryTransport, TRACEPARENT_META_KEY } from '@modelcontextprotocol/server';
import { SpanKind, SpanStatusCode } from '@opentelemetry/api';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { principalFromCredential } from '../../src/core/registry.js';
import { createSteelMcpServer } from '../../src/core/server.js';
import { TEST_API_KEY, testDeps } from '../helpers/fakes.js';
import { type TracingHarness, tracingHarness } from '../helpers/tracing.js';

const TRACE_ID = '4bf92f3577b34da6a3ce929d0e0e4736';
const SPAN_ID = '00f067aa0ba902b7';

type Deps = ReturnType<typeof testDeps>;

interface Harness {
    client: Client;
    deps: Deps;
    tracing: TracingHarness;
    close(): Promise<void>;
}

async function connect(): Promise<Harness> {
    const tracing = tracingHarness();
    const deps = testDeps({ tracer: tracing.tracer });
    const server = createSteelMcpServer(deps);
    const [clientTransport, serverTransport] = InMemoryTransport.createLinkedPair();
    const client = new Client({ name: 'tracing-test', version: '1.0.0' });
    await server.connect(serverTransport);
    await client.connect(clientTransport);
    return {
        client,
        deps,
        tracing,
        close: async () => {
            await client.close();
            await server.close();
            await tracing.shutdown();
        },
    };
}

let harness: Harness;

beforeEach(async () => {
    harness = await connect();
});

afterEach(async () => {
    await harness.close();
});

describe('tool-call spans', () => {
    it('records exactly one span per tool call, named after the method and the tool', async () => {
        await harness.client.callTool({ name: 'steel_scrape', arguments: { url: 'https://example.com' } });

        const spans = harness.tracing.spans();
        expect(spans).toHaveLength(1);
        expect(spans[0]!.name).toBe('tools/call steel_scrape');
        expect(spans[0]!.kind).toBe(SpanKind.SERVER);
        expect(spans[0]!.status.code).toBe(SpanStatusCode.UNSET);
    });

    it('carries the tool name, the profile and the principal digest, and nothing else', async () => {
        await harness.client.callTool({ name: 'steel_scrape', arguments: { url: 'https://example.com' } });

        expect(harness.tracing.span('tools/call steel_scrape').attributes).toEqual({
            'mcp.method.name': 'tools/call',
            'mcp.tool.name': 'steel_scrape',
            'steel.profile': 'browse',
            'steel.deployment': 'cloud',
            'steel.principal': principalFromCredential(TEST_API_KEY),
        });
    });

    it('traces a stateful tool the same way', async () => {
        const created = await harness.client.callTool({ name: 'steel_session_create', arguments: {} });
        const sessionId = (created as { structuredContent?: { session_id?: string } }).structuredContent?.session_id;
        harness.tracing.reset();

        await harness.client.callTool({
            name: 'steel_navigate',
            arguments: { session_id: sessionId, url: 'https://example.com/next' },
        });

        expect(harness.tracing.span('tools/call steel_navigate').attributes['mcp.tool.name']).toBe('steel_navigate');
    });

    it('starts a root span when the caller sends no trace context', async () => {
        await harness.client.callTool({ name: 'steel_scrape', arguments: { url: 'https://example.com' } });
        expect(harness.tracing.span('tools/call steel_scrape').parentSpanContext).toBeUndefined();
    });
});

describe('session-release spans', () => {
    it('records one allow-listed lifecycle cause and no session identity', async () => {
        const created = await harness.client.callTool({ name: 'steel_session_create', arguments: {} });
        const sessionId = (created as { structuredContent?: { session_id?: string } }).structuredContent?.session_id;
        harness.tracing.reset();

        await harness.client.callTool({ name: 'steel_session_release', arguments: { session_id: sessionId } });

        const release = harness.tracing.span('steel session released');
        expect(release.kind).toBe(SpanKind.INTERNAL);
        expect(release.attributes).toEqual({
            'steel.session.release_cause': 'explicit',
            'steel.deployment': 'cloud',
            'steel.registry.backend': 'memory',
        });
        expect(JSON.stringify(release.attributes)).not.toMatch(
            /handle|principal|profile|url|page|credential|token|cookie/i
        );
    });
});

describe('inbound trace context', () => {
    it('parents the tool span on the traceparent the client put in _meta', async () => {
        await harness.client.callTool({
            name: 'steel_scrape',
            arguments: { url: 'https://example.com' },
            _meta: { [TRACEPARENT_META_KEY]: `00-${TRACE_ID}-${SPAN_ID}-01` },
        });

        const span = harness.tracing.span('tools/call steel_scrape');
        expect(span.spanContext().traceId).toBe(TRACE_ID);
        expect(span.parentSpanContext?.spanId).toBe(SPAN_ID);
    });

    it('ignores an unusable traceparent and traces the call anyway', async () => {
        await harness.client.callTool({
            name: 'steel_scrape',
            arguments: { url: 'https://example.com' },
            _meta: { [TRACEPARENT_META_KEY]: 'not-a-traceparent' },
        });

        const span = harness.tracing.span('tools/call steel_scrape');
        expect(span.parentSpanContext).toBeUndefined();
        expect(span.spanContext().traceId).not.toBe(TRACE_ID);
    });
});

describe('failed tool calls', () => {
    it('marks the span as failed with the error code, and still answers the caller', async () => {
        const result = await harness.client.callTool({
            name: 'steel_navigate',
            arguments: { session_id: 'sess_nope', url: 'https://example.com' },
        });

        expect((result as { isError?: boolean }).isError).toBe(true);
        const span = harness.tracing.span('tools/call steel_navigate');
        expect(span.status.code).toBe(SpanStatusCode.ERROR);
        expect(span.attributes['error.type']).toBe('not_found');
    });

    it('records no exception message, which can quote page content', async () => {
        await harness.client.callTool({
            name: 'steel_navigate',
            arguments: { session_id: 'sess_nope', url: 'https://example.com' },
        });

        const span = harness.tracing.span('tools/call steel_navigate');
        expect(span.events).toEqual([]);
        expect(span.status.message).toBeUndefined();
    });
});

describe('span redaction', () => {
    it('never puts the credential in a span, even though the config holds it', async () => {
        expect(harness.deps.config.apiKey).toBe(TEST_API_KEY);
        await harness.client.callTool({ name: 'steel_scrape', arguments: { url: 'https://example.com' } });
        await harness.client.callTool({ name: 'steel_session_create', arguments: {} });
        await harness.client.callTool({
            name: 'steel_navigate',
            arguments: { session_id: 'sess_nope', url: 'https://example.com' },
        });

        const recorded = JSON.stringify(
            harness.tracing.spans().map(span => ({
                name: span.name,
                attributes: span.attributes,
                status: span.status,
                events: span.events,
            }))
        );
        expect(recorded).not.toContain(TEST_API_KEY);
        expect(recorded).toContain(principalFromCredential(TEST_API_KEY));
    });
});

describe('response bytes', () => {
    it('are identical whether or not a tracer is recording', async () => {
        const at = () => new Date('2026-07-30T12:00:00.000Z');

        const tracing = tracingHarness();
        const traced = testDeps({ tracer: tracing.tracer });
        traced.now = at;
        const untraced = testDeps();
        untraced.now = at;

        const results: string[] = [];
        for (const deps of [traced, untraced]) {
            const server = createSteelMcpServer(deps);
            const [clientTransport, serverTransport] = InMemoryTransport.createLinkedPair();
            const client = new Client({ name: 'bytes', version: '1.0.0' });
            await server.connect(serverTransport);
            await client.connect(clientTransport);
            results.push(
                JSON.stringify(
                    await client.callTool({ name: 'steel_scrape', arguments: { url: 'https://example.com' } })
                )
            );
            await client.close();
            await server.close();
        }

        expect(tracing.spans()).toHaveLength(1);
        expect(results[0]).toBe(results[1]);
        await tracing.shutdown();
    });
});

// ABOUTME: A fake Chrome DevTools Protocol endpoint over wss, answering the four commands the session
// ABOUTME: viewer sends, emitting screencast frames, and recording every ack so a stall shows up.
import { execFileSync } from 'node:child_process';
import { existsSync, mkdtempSync, readFileSync } from 'node:fs';
import { createServer, type Server } from 'node:https';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { type WebSocket, WebSocketServer } from 'ws';

/** The `openssl` this machine has, or `null`; the server needs it to mint its own certificate. */
export function findOpenssl(): string | null {
    const configured = process.env.OPENSSL_PATH;
    if (configured !== undefined && configured !== '') return existsSync(configured) ? configured : null;
    return ['/usr/bin/openssl', '/opt/homebrew/bin/openssl', '/usr/local/bin/openssl'].find(existsSync) ?? null;
}

/** One command the app sent, exactly as it arrived. */
export interface CdpCommand {
    id: number;
    method: string;
    params: Record<string, unknown>;
    /** The flat-mode target session, absent when the app sent the command browser-wide. */
    sessionId?: string;
}

/** A target as `Target.getTargets` reports it. */
export interface FakeTargetInfo {
    targetId: string;
    type: string;
    url: string;
    title?: string;
}

export interface FakeCdpOptions {
    /** Commands the endpoint accepts and never answers, to run the app's own command timeout. */
    stall?: readonly string[];
    /** Commands the endpoint refuses, mapped to the message it refuses them with. */
    refuse?: Readonly<Record<string, string>>;
    /**
     * What `Target.getTargets` reports.
     *
     * The default puts a DevTools page ahead of the real one, so the app's target picking has to skip
     * it rather than screencast the inspector.
     */
    targets?: readonly FakeTargetInfo[];
    /** The flat session id `Target.attachToTarget` hands back, or `null` to hand back none. */
    attachedSessionId?: string | null;
}

const DEFAULT_TARGETS: readonly FakeTargetInfo[] = [
    { targetId: 'devtools-1', type: 'page', url: 'devtools://devtools/bundled/inspector.html' },
    { targetId: 'page-1', type: 'page', url: 'https://example.com/', title: 'Example' },
];

/** The metadata a real `Page.screencastFrame` carries, with the app's defaults for a 1024x768 page. */
export interface FakeFrameMetadata {
    offsetTop: number;
    pageScaleFactor: number;
    deviceWidth: number;
    deviceHeight: number;
    scrollOffsetX: number;
    scrollOffsetY: number;
    timestamp: number;
}

export function frameMetadata(overrides: Partial<FakeFrameMetadata> = {}): FakeFrameMetadata {
    return {
        offsetTop: 0,
        pageScaleFactor: 1,
        deviceWidth: 1024,
        deviceHeight: 768,
        scrollOffsetX: 0,
        scrollOffsetY: 0,
        timestamp: Date.now() / 1000,
        ...overrides,
    };
}

let certificate: { key: string; cert: string } | null = null;

/**
 * Mints one throwaway TLS certificate for the whole test process.
 *
 * The app opens `wss:` and nothing else — that is enforced by `validateCdpUrl` and again by the
 * document's own CSP — so the fake endpoint has to speak TLS. The certificate is self-signed and
 * generated per run rather than checked in, and the browser is told to ignore certificate errors.
 */
function tlsCertificate(openssl: string): { key: string; cert: string } {
    if (certificate) return certificate;
    const directory = mkdtempSync(join(tmpdir(), 'steel-viewer-tls-'));
    const keyPath = join(directory, 'key.pem');
    const certPath = join(directory, 'cert.pem');
    execFileSync(
        openssl,
        [
            'req',
            '-x509',
            '-newkey',
            'rsa:2048',
            '-nodes',
            '-keyout',
            keyPath,
            '-out',
            certPath,
            '-days',
            '2',
            '-subj',
            '/CN=localhost',
        ],
        { stdio: 'ignore' }
    );
    certificate = { key: readFileSync(keyPath, 'utf8'), cert: readFileSync(certPath, 'utf8') };
    return certificate;
}

/**
 * A CDP endpoint the app can really connect to.
 *
 * It answers the commands `attach()` sends, refuses a page-scoped command that arrives without the
 * session id it handed out, and records every ack, so "the ack is sent for every frame" becomes
 * something a test can read rather than something the source implies.
 */
export class FakeCdpServer {
    /** Every command the app sent, in arrival order. */
    readonly received: CdpCommand[] = [];
    /** The `sessionId` argument of every `Page.screencastFrameAck`, in arrival order. */
    readonly acks: unknown[] = [];
    /** Things the app did that a real Chrome would have refused. */
    readonly violations: string[] = [];
    /** The request target of each connection, so a test can check the URL was used byte for byte. */
    readonly connectedPaths: string[] = [];
    /** Set once the app closes the socket. */
    closedByApp = false;

    private socket: WebSocket | null = null;
    private nextFrameSessionId = 1;

    private constructor(
        private readonly server: Server,
        private readonly sockets: WebSocketServer,
        /** The URL the live-view tool should hand the app, credential and all. */
        readonly url: string,
        /** The credential inside `url`, which must never reach the app's DOM. */
        readonly token: string,
        private readonly options: FakeCdpOptions
    ) {}

    static async start(openssl: string, options: FakeCdpOptions = {}): Promise<FakeCdpServer> {
        const server = createServer(tlsCertificate(openssl));
        const sockets = new WebSocketServer({ server });
        await new Promise<void>(resolve => server.listen(0, '127.0.0.1', resolve));
        const address = server.address();
        if (address === null || typeof address === 'string') throw new Error('the fake CDP server has no port');
        const token = [REDACTED]}`;
        const url = `wss://127.0.0.1:${address.port}/v1/devtools/browser/abc123?token=${token}`;
        const fake = new FakeCdpServer(server, sockets, url, token, options);
        sockets.on('connection', (socket, request) => fake.accept(socket, request.url ?? ''));
        return fake;
    }

    get connectionCount(): number {
        return this.connectedPaths.length;
    }

    /** The methods the app sent, in order — what an attach sequence assertion reads. */
    get methods(): string[] {
        return this.received.map(command => command.method);
    }

    /** The Input.* commands the app forwarded, in arrival order — what a take-control test reads. */
    get inputCommands(): CdpCommand[] {
        return this.received.filter(command => command.method.startsWith('Input.'));
    }

    /** Waits until the app has opened a socket. */
    async waitForConnection(timeoutMs = 10_000): Promise<void> {
        const deadline = Date.now() + timeoutMs;
        while (this.socket === null) {
            if (Date.now() >= deadline) throw new Error(`the app never connected within ${timeoutMs}ms`);
            await new Promise(resolve => setTimeout(resolve, 25));
        }
    }

    /** Waits until the app has sent `method` at least `count` times, then returns those commands. */
    async waitFor(method: string, count = 1, timeoutMs = 10_000): Promise<CdpCommand[]> {
        const deadline = Date.now() + timeoutMs;
        for (;;) {
            const matching = this.received.filter(command => command.method === method);
            if (matching.length >= count) return matching;
            if (Date.now() >= deadline) {
                throw new Error(
                    `the app sent ${method} ${matching.length} times in ${timeoutMs}ms, expected ${count}; ` +
                        `it sent ${JSON.stringify(this.methods)}`
                );
            }
            await new Promise(resolve => setTimeout(resolve, 25));
        }
    }

    /**
     * Emits one `Page.screencastFrame` and returns the frame session id it used.
     *
     * That id is an integer, as Chrome types it, and `Page.screencastFrameAck` has to echo it back
     * unchanged or a real browser sends nothing further.
     */
    sendFrame(base64Jpeg: string, metadata: FakeFrameMetadata = frameMetadata()): number {
        if (this.socket === null) throw new Error('no app is connected, so no frame can be sent');
        const sessionId = this.nextFrameSessionId++;
        this.socket.send(
            JSON.stringify({
                method: 'Page.screencastFrame',
                sessionId: this.attachedSessionId,
                params: { data: base64Jpeg, sessionId, metadata },
            })
        );
        return sessionId;
    }

    /** Tells the controlling viewer that the remote page opened an input[type=file]. */
    sendFileChooser(backendNodeId = 42): void {
        if (this.socket === null) throw new Error('no app is connected, so no file chooser can be sent');
        this.socket.send(
            JSON.stringify({
                method: 'Page.fileChooserOpened',
                sessionId: this.attachedSessionId,
                params: { mode: 'selectSingle', backendNodeId },
            })
        );
    }

    /**
     * Sends a payload straight down the socket, bypassing the CDP shape entirely.
     *
     * Everything CDP sends the app is JSON text, so this is how a test checks the app's guard against
     * a binary frame or a payload that does not parse.
     */
    sendRaw(payload: string | Buffer): void {
        if (this.socket === null) throw new Error('no app is connected, so nothing can be sent');
        this.socket.send(payload);
    }

    /** Drops the connection the way a browser that has gone away does. */
    dropConnection(): void {
        this.socket?.terminate();
    }

    async stop(): Promise<void> {
        this.socket?.terminate();
        await new Promise<void>(resolve => this.sockets.close(() => resolve()));
        await new Promise<void>(resolve => this.server.close(() => resolve()));
    }

    private get attachedSessionId(): string | null {
        return this.options.attachedSessionId === undefined ? 'page-session-1' : this.options.attachedSessionId;
    }

    private accept(socket: WebSocket, path: string): void {
        this.connectedPaths.push(path);
        this.socket = socket;
        socket.on('close', () => {
            this.closedByApp = true;
        });
        socket.on('message', raw => this.handle(socket, raw.toString()));
    }

    private handle(socket: WebSocket, raw: string): void {
        const command = JSON.parse(raw) as CdpCommand;
        this.received.push(command);
        if (command.method === 'Page.screencastFrameAck') this.acks.push(command.params.sessionId);

        // Everything after the attach is page-scoped, and a real Chrome answers "session not found"
        // when a command that needs one arrives without it.
        const scoped = command.method !== 'Target.getTargets' && command.method !== 'Target.attachToTarget';
        if (scoped && this.attachedSessionId !== null && command.sessionId !== this.attachedSessionId) {
            this.violations.push(`${command.method} arrived with sessionId ${JSON.stringify(command.sessionId)}`);
            this.fail(socket, command, 'Session with given id not found.');
            return;
        }
        if (this.options.stall?.includes(command.method)) return;
        const refusal = this.options.refuse?.[command.method];
        if (refusal !== undefined) {
            this.fail(socket, command, refusal);
            return;
        }

        if (command.method === 'Target.getTargets') {
            this.reply(socket, command, { targetInfos: this.options.targets ?? DEFAULT_TARGETS });
            return;
        }
        if (command.method === 'Target.attachToTarget') {
            if (command.params.flatten !== true) this.violations.push('Target.attachToTarget without flatten: true');
            this.reply(socket, command, this.attachedSessionId === null ? {} : { sessionId: this.attachedSessionId });
            return;
        }
        if (command.method === 'DOM.resolveNode') {
            this.reply(socket, command, { object: { type: 'object', objectId: 'remote-file-input-1' } });
            return;
        }
        if (command.method === 'Runtime.evaluate') {
            this.reply(socket, command, { result: { type: 'string', value: 'https://example.com' } });
            return;
        }
        if (command.method === 'Runtime.callFunctionOn') {
            this.reply(socket, command, { result: { type: 'boolean', value: true } });
            return;
        }
        if (command.method === 'Page.screencastFrameAck' && !Number.isInteger(command.params.sessionId)) {
            // Chrome types this argument as int32 and rejects anything else, which stalls the stream.
            this.violations.push('Page.screencastFrameAck with a non-integer sessionId');
            this.fail(socket, command, 'Failed to deserialize params.sessionId - BINDINGS: int32 value expected');
            return;
        }
        this.reply(socket, command, {});
    }

    private reply(socket: WebSocket, command: CdpCommand, result: unknown): void {
        socket.send(JSON.stringify({ id: command.id, sessionId: command.sessionId, result }));
    }

    private fail(socket: WebSocket, command: CdpCommand, message: string): void {
        socket.send(JSON.stringify({ id: command.id, sessionId: command.sessionId, error: { code: -32602, message } }));
    }
}

// ABOUTME: Unit tests for the entrypoint's optional OTLP wiring: off unless a standard OTEL variable
// ABOUTME: asks for it, and degrading to a warning rather than a crash when the SDK is not installed.
import { describe, expect, it } from 'vitest';
import { startTracing, tracingRequested } from '../../src/tracing.js';
import { fakeTracingStarter } from '../helpers/tracing.js';

describe('tracingRequested', () => {
    it('is false for an environment that says nothing about telemetry', () => {
        expect(tracingRequested({})).toBe(false);
        expect(tracingRequested({ STEEL_API_KEY: 'k' })).toBe(false);
    });

    it('is true for either OTLP endpoint variable', () => {
        expect(tracingRequested({ OTEL_EXPORTER_OTLP_ENDPOINT: 'http://collector:4318' })).toBe(true);
        expect(tracingRequested({ OTEL_EXPORTER_OTLP_TRACES_ENDPOINT: 'http://collector:4318/v1/traces' })).toBe(true);
    });

    it('is true when an exporter is named explicitly', () => {
        expect(tracingRequested({ OTEL_TRACES_EXPORTER: 'otlp' })).toBe(true);
    });

    it('honours the standard kill switches', () => {
        expect(tracingRequested({ OTEL_EXPORTER_OTLP_ENDPOINT: 'http://c:4318', OTEL_SDK_DISABLED: 'true' })).toBe(
            false
        );
        expect(tracingRequested({ OTEL_EXPORTER_OTLP_ENDPOINT: 'http://c:4318', OTEL_TRACES_EXPORTER: 'none' })).toBe(
            false
        );
    });

    it('ignores a variable that is present but blank', () => {
        expect(tracingRequested({ OTEL_EXPORTER_OTLP_ENDPOINT: '   ' })).toBe(false);
    });
});

describe('startTracing', () => {
    it('does not touch the SDK when nothing asked for tracing', async () => {
        const starter = fakeTracingStarter();
        expect(await startTracing({}, { start: starter.start })).toBeUndefined();
        expect(starter.started).toEqual([]);
    });

    it('starts one pipeline under the default service name', async () => {
        const starter = fakeTracingStarter();
        const handle = await startTracing(
            { OTEL_EXPORTER_OTLP_ENDPOINT: 'http://collector:4318' },
            { start: starter.start }
        );

        expect(starter.started).toEqual([{ serviceName: 'steel-mcp' }]);
        await handle?.shutdown();
        expect(starter.shutdownCount()).toBe(1);
    });

    it('respects an operator-chosen service name', async () => {
        const starter = fakeTracingStarter();
        await startTracing(
            { OTEL_EXPORTER_OTLP_ENDPOINT: 'http://collector:4318', OTEL_SERVICE_NAME: 'steel-mcp-staging' },
            { start: starter.start }
        );
        expect(starter.started).toEqual([{ serviceName: 'steel-mcp-staging' }]);
    });

    it('warns and carries on serving when the optional SDK packages are absent', async () => {
        const starter = fakeTracingStarter({ failWith: new Error("Cannot find module '@opentelemetry/sdk-node'") });
        const warnings: string[] = [];

        const handle = await startTracing(
            { OTEL_EXPORTER_OTLP_ENDPOINT: 'http://collector:4318' },
            { start: starter.start, onWarn: message => warnings.push(message) }
        );

        expect(handle).toBeUndefined();
        expect(warnings).toHaveLength(1);
        expect(warnings[0]).toContain('@opentelemetry/sdk-node');
    });
});

// ABOUTME: Builds a fake page-scoped CDP session from a declarative node tree, producing the exact
// ABOUTME: Accessibility.getFullAXTree and DOMSnapshot.captureSnapshot payloads the pipeline joins.
import { COMPUTED_STYLES } from '../../src/core/snapshot.js';
import type { CdpEventParams, CdpSession } from '../../src/core/steel/cdp.js';

/** One node in a fixture page. Omitting `bounds` models a node the layout engine never rendered. */
export interface FixtureNode {
    tag: string;
    backendNodeId: number;
    /** ARIA role. Omit to leave the node out of the accessibility tree entirely. */
    role?: string;
    name?: string;
    /** Marked ignored by Chrome (aria-hidden, presentational, etc.). */
    ignored?: boolean;
    attributes?: Record<string, string>;
    inputValue?: string;
    /** `[x, y, width, height]` in CSS pixels. Absent means not in the layout tree. */
    bounds?: [number, number, number, number];
    pointerEvents?: string;
    visibility?: string;
    /** Computed styles beyond the defaults, such as an iframe's border and padding. */
    computed?: Record<string, string>;
    /** AX properties such as level, checked, disabled. */
    properties?: Record<string, string | number | boolean>;
    children?: FixtureNode[];
    /** The document this node holds, which makes it an iframe with its own frame and AX tree. */
    frame?: FixtureFrame;
}

/** A document nested inside a fixture page, with its own coordinate space and node ids. */
export interface FixtureFrame {
    root: FixtureNode;
    frameId: string;
    /** The loader of the frame's current document. Defaults to one derived from the frame id. */
    loaderId?: string;
    url?: string;
    scroll?: { x: number; y: number };
    /** Models a frame that went away between the DOM snapshot and the read of its tree. */
    detached?: boolean;
    /** Models a transport or session failure while reading this frame's tree. */
    readError?: string;
    /**
     * Models a frame that replaced its DOM between the DOM snapshot and the read of its tree: the
     * accessibility tree names backend node ids the DOM snapshot has never seen.
     */
    rerendered?: boolean;
}

export interface FixturePage {
    root: FixtureNode;
    loaderId?: string;
    url?: string;
    title?: string;
    frameId?: string;
    viewport?: { width: number; height: number };
    scroll?: { x: number; y: number };
}

interface FlatNode {
    node: FixtureNode;
    index: number;
    parentIndex: number;
}

/** One document's worth of the fixture: its own nodes, indices and frame identity. */
interface FixtureDocument {
    frameId: string;
    loaderId: string;
    url: string;
    scroll: { x: number; y: number };
    flat: FlatNode[];
    detached: boolean;
    readError?: string | undefined;
    /** Added to every backend node id the accessibility tree reports, to model a re-rendered frame. */
    axIdOffset: number;
    /** Which node of which document holds this one, absent on the top document. */
    owner?: { documentIndex: number; nodeIndex: number };
}

/** Backend node ids a re-rendered frame reports, chosen to collide with nothing the fixture issues. */
const RERENDERED_ID_OFFSET = 100_000;

/** Flattens one document, stopping at an iframe rather than walking into the document it holds. */
function flatten(root: FixtureNode): FlatNode[] {
    const flat: FlatNode[] = [];
    const walk = (node: FixtureNode, parentIndex: number): void => {
        const index = flat.length;
        flat.push({ node, index, parentIndex });
        for (const child of node.children ?? []) walk(child, index);
    };
    walk(root, -1);
    return flat;
}

/** Splits a fixture page into one entry per frame, top document first, with per-document indices. */
function collectDocuments(page: FixturePage): FixtureDocument[] {
    const documents: FixtureDocument[] = [
        {
            frameId: page.frameId ?? 'main-frame',
            loaderId: page.loaderId ?? 'loader-1',
            url: page.url ?? 'https://example.com/',
            scroll: page.scroll ?? { x: 0, y: 0 },
            flat: flatten(page.root),
            detached: false,
            axIdOffset: 0,
        },
    ];

    for (let at = 0; at < documents.length; at++) {
        for (const entry of documents[at]!.flat) {
            const frame = entry.node.frame;
            if (!frame) continue;
            documents.push({
                frameId: frame.frameId,
                loaderId: frame.loaderId ?? `loader-${frame.frameId}`,
                url: frame.url ?? 'https://example.com/frame',
                scroll: frame.scroll ?? { x: 0, y: 0 },
                flat: flatten(frame.root),
                detached: frame.detached ?? false,
                readError: frame.readError,
                axIdOffset: frame.rerendered ? RERENDERED_ID_OFFSET : 0,
                owner: { documentIndex: at, nodeIndex: entry.index },
            });
        }
    }
    return documents;
}

interface FrameTree {
    frame: { id: string; loaderId: string; url: string };
    childFrames?: FrameTree[];
}

/** The `Page.getFrameTree` answer: every document nested under the one that holds it. */
function frameTreeOf(documents: FixtureDocument[], at: number): FrameTree {
    const document = documents[at]!;
    const children = documents
        .map((candidate, index) => ({ candidate, index }))
        .filter(({ candidate }) => candidate.owner?.documentIndex === at)
        .map(({ index }) => frameTreeOf(documents, index));
    return {
        frame: { id: document.frameId, loaderId: document.loaderId, url: document.url },
        ...(children.length > 0 ? { childFrames: children } : {}),
    };
}

class StringTable {
    readonly strings: string[] = [];
    private readonly index = new Map<string, number>();

    intern(value: string): number {
        const existing = this.index.get(value);
        if (existing !== undefined) return existing;
        this.strings.push(value);
        const at = this.strings.length - 1;
        this.index.set(value, at);
        return at;
    }
}

/** The computed styles the snapshot pipeline asks DOMSnapshot for. Read back by position, so the
 * fixture has to emit them in the order the pipeline requests them. */
export const REQUESTED_COMPUTED_STYLES: readonly string[] = COMPUTED_STYLES;

const DEFAULT_COMPUTED: Record<string, string> = {
    'pointer-events': 'auto',
    visibility: 'visible',
    display: 'block',
    opacity: '1',
    'border-left-width': '0px',
    'border-top-width': '0px',
    'padding-left': '0px',
    'padding-top': '0px',
};

function buildAxTree(flat: FlatNode[], idOffset: number) {
    const axNodes = flat
        .filter(entry => entry.node.role !== undefined)
        .map(entry => {
            const { node } = entry;
            const childIds = flat
                .filter(child => child.parentIndex === entry.index && child.node.role !== undefined)
                .map(child => String(child.index));
            return {
                nodeId: String(entry.index),
                ignored: node.ignored ?? false,
                role: { type: 'role', value: node.role },
                name: node.name === undefined ? undefined : { type: 'computedString', value: node.name },
                value: node.inputValue === undefined ? undefined : { type: 'string', value: node.inputValue },
                properties: Object.entries(node.properties ?? {}).map(([name, value]) => ({
                    name,
                    value: { type: typeof value, value },
                })),
                childIds,
                backendDOMNodeId: node.backendNodeId + idOffset,
                parentId: entry.parentIndex >= 0 ? String(entry.parentIndex) : undefined,
            };
        });
    return { nodes: axNodes };
}

function buildDomSnapshot(documents: FixtureDocument[], page: FixturePage) {
    const table = new StringTable();

    // Which node in this document holds which other document, in the shape Chrome sends: a node
    // index paired with the index of the held document in this same list.
    const heldBy = documents.map(() => ({ index: [] as number[], value: [] as number[] }));
    documents.forEach((document, at) => {
        if (!document.owner) return;
        const link = heldBy[document.owner.documentIndex]!;
        link.index.push(document.owner.nodeIndex);
        link.value.push(at);
    });

    const built = documents.map((document, at) => {
        const { flat } = document;
        const layoutNodeIndex: number[] = [];
        const layoutStyles: number[][] = [];
        const layoutBounds: number[][] = [];
        const inputValueIndex: number[] = [];
        const inputValueValue: number[] = [];
        const isClickableIndex: number[] = [];

        for (const { node, index } of flat) {
            if (node.inputValue !== undefined) {
                inputValueIndex.push(index);
                inputValueValue.push(table.intern(node.inputValue));
            }
            if (node.role === 'button' || node.role === 'link' || node.tag === 'BUTTON' || node.tag === 'A') {
                isClickableIndex.push(index);
            }
            if (!node.bounds) continue;
            const computed: Record<string, string> = {
                ...DEFAULT_COMPUTED,
                'pointer-events': node.pointerEvents ?? DEFAULT_COMPUTED['pointer-events']!,
                visibility: node.visibility ?? DEFAULT_COMPUTED.visibility!,
                ...node.computed,
            };
            layoutNodeIndex.push(index);
            layoutStyles.push(REQUESTED_COMPUTED_STYLES.map(name => table.intern(computed[name] ?? '')));
            layoutBounds.push([...node.bounds]);
        }

        return {
            documentURL: table.intern(document.url),
            title: table.intern(at === 0 ? (page.title ?? 'Example') : ''),
            baseURL: table.intern(document.url),
            frameId: table.intern(document.frameId),
            nodes: {
                parentIndex: flat.map(entry => entry.parentIndex),
                nodeType: flat.map(entry => (entry.node.tag === '#text' ? 3 : 1)),
                nodeName: flat.map(entry => table.intern(entry.node.tag)),
                nodeValue: flat.map(entry => table.intern(entry.node.attributes?.['#value'] ?? '')),
                backendNodeId: flat.map(entry => entry.node.backendNodeId),
                attributes: flat.map(entry =>
                    Object.entries(entry.node.attributes ?? {})
                        .filter(([name]) => name !== '#value')
                        .flatMap(([name, value]) => [table.intern(name), table.intern(value)])
                ),
                inputValue: { index: inputValueIndex, value: inputValueValue },
                isClickable: { index: isClickableIndex },
                contentDocumentIndex: heldBy[at],
            },
            layout: {
                nodeIndex: layoutNodeIndex,
                styles: layoutStyles,
                bounds: layoutBounds,
                text: layoutNodeIndex.map(() => -1),
            },
            scrollOffsetX: document.scroll.x,
            scrollOffsetY: document.scroll.y,
        };
    });

    return { strings: table.strings, documents: built };
}

export interface FixtureSession {
    session: CdpSession;
    sent: Array<{ method: string; params: Record<string, unknown> }>;
    emit(event: string, params: CdpEventParams): void;
    listenerCount(event: string): number;
    /** Replaces the page the fixture serves, modelling a navigation or a DOM change. */
    setPage(page: FixturePage): void;
    /** Canned answers for methods the pipeline calls but the fixture does not model. */
    stub(method: string, handler: (params: Record<string, unknown>) => unknown): void;
}

/** Builds a fake page-scoped CDP session that answers the four calls the snapshot pipeline makes. */
export function fixtureSession(initialPage: FixturePage): FixtureSession {
    let page = initialPage;
    const sent: Array<{ method: string; params: Record<string, unknown> }> = [];
    const listeners = new Map<string, Set<(params: CdpEventParams) => void>>();
    const stubs = new Map<string, (params: Record<string, unknown>) => unknown>();

    const session: CdpSession = {
        async send<T>(method: string, params: Record<string, unknown> = {}): Promise<T> {
            sent.push({ method, params });
            const stub = stubs.get(method);
            if (stub) return stub(params) as T;

            const documents = collectDocuments(page);
            switch (method) {
                case 'Page.getFrameTree':
                    return { frameTree: frameTreeOf(documents, 0) } as T;
                case 'Accessibility.getFullAXTree': {
                    // Chrome answers for one frame: the page's own when asked for no frame in
                    // particular, and it refuses a frame it does not have.
                    const asked = params.frameId as string | undefined;
                    const document =
                        asked === undefined ? documents[0] : documents.find(entry => entry.frameId === asked);
                    if (!document || document.detached) throw new Error('Frame with the given frameId is not found.');
                    if (document.readError !== undefined) throw new Error(document.readError);
                    return buildAxTree(document.flat, document.axIdOffset) as T;
                }
                case 'DOMSnapshot.captureSnapshot':
                    return buildDomSnapshot(documents, page) as T;
                case 'Page.getLayoutMetrics':
                    return {
                        cssLayoutViewport: {
                            clientWidth: page.viewport?.width ?? 1280,
                            clientHeight: page.viewport?.height ?? 720,
                            pageX: page.scroll?.x ?? 0,
                            pageY: page.scroll?.y ?? 0,
                        },
                        cssContentSize: { width: 1280, height: 4000 },
                    } as T;
                case 'Runtime.evaluate':
                    return { result: { value: false } } as T;
                default:
                    return {} as T;
            }
        },
        on(event, listener) {
            const set = listeners.get(event) ?? new Set();
            set.add(listener);
            listeners.set(event, set);
            return () => set.delete(listener);
        },
        async close() {},
    };

    return {
        session,
        sent,
        listenerCount: event => listeners.get(event)?.size ?? 0,
        emit(event, params) {
            for (const listener of listeners.get(event) ?? []) listener(params);
        },
        setPage(next) {
            page = next;
        },
        stub(method, handler) {
            stubs.set(method, handler);
        },
    };
}

// ABOUTME: Unit tests for the Redis client adapter: each registry command maps to the right client
// ABOUTME: call, including the millisecond expiry, and a connection error is reported, never thrown.
import { describe, expect, it } from 'vitest';
import { redisConnection } from '../../src/core/redis.js';
import { RecordingRedisClient } from '../helpers/fake-redis.js';

function connection(client: RecordingRedisClient, onError: (error: unknown) => void = () => {}) {
    return redisConnection(client, onError);
}

describe('redisConnection commands', () => {
    it('sets a value with a millisecond expiry, the only TTL unit the registry uses', async () => {
        const client = new RecordingRedisClient();
        await connection(client).commands.set('steel-mcp:handle:sess_1', '{}', 90_000);

        expect(client.calls).toEqual([{ command: 'set', args: ['steel-mcp:handle:sess_1', '{}', 'PX', 90_000] }]);
    });

    it('passes reads, deletes and set membership straight through', async () => {
        const client = new RecordingRedisClient({ get: '{"handle":"sess_1"}', del: 1, smembers: ['sess_1'] });
        const commands = connection(client).commands;

        expect(await commands.get('key')).toBe('{"handle":"sess_1"}');
        expect(await commands.del('key')).toBe(1);
        expect(await commands.smembers('index')).toEqual(['sess_1']);
        await commands.sadd('index', 'sess_1');
        await commands.srem('index', 'sess_1');

        expect(client.calls.map(call => call.command)).toEqual(['get', 'del', 'smembers', 'sadd', 'srem']);
        expect(client.calls.at(-1)?.args).toEqual(['index', 'sess_1']);
    });

    it('reports how many keys a delete removed, which is what settles a concurrent sweep', async () => {
        expect(await connection(new RecordingRedisClient({ del: 0 })).commands.del('gone')).toBe(0);
    });

    it('increments a counter and expires it in milliseconds, as two commands', async () => {
        // INCR creates its key with no expiry, so the TTL cannot ride along with the increment.
        const client = new RecordingRedisClient({ incr: 2 });
        const commands = connection(client).commands;

        expect(await commands.incr('steel-mcp:handle:sess_1:rounds')).toBe(2);
        await commands.pexpire('steel-mcp:handle:sess_1:rounds', 90_000);

        expect(client.calls).toEqual([
            { command: 'incr', args: ['steel-mcp:handle:sess_1:rounds'] },
            { command: 'pexpire', args: ['steel-mcp:handle:sess_1:rounds', 90_000] },
        ]);
    });

    it('maps lease claims and fenced updates to atomic Redis operations', async () => {
        const client = new RecordingRedisClient();
        const commands = connection(client).commands;

        expect(await commands.setIfAbsent('control', 'lease-1', 60_000)).toBe(true);
        expect(await commands.compareSet('control', 'lease-1', 'lease-2', 60_000)).toBe(true);
        expect(await commands.compareDelete('control', 'lease-2')).toBe(true);

        expect(client.calls[0]).toEqual({ command: 'set', args: ['control', 'lease-1', 'PX', 60_000, 'NX'] });
        expect(client.calls.slice(1).map(call => call.command)).toEqual(['eval', 'eval']);
        expect(client.calls[1]?.args).toContain('lease-1');
        expect(client.calls[2]?.args).toContain('lease-2');
    });
});

describe('redisConnection lifecycle', () => {
    it('reports a client error instead of letting it take the replica down', () => {
        // An ioredis client with no error listener turns a reconnect into an uncaught exception.
        const failures: unknown[] = [];
        const client = new RecordingRedisClient();
        connection(client, error => failures.push(error));

        client.emitError(new Error('ECONNREFUSED'));

        expect(failures.map(String)).toEqual(['Error: ECONNREFUSED']);
    });

    it('quits the client on close, so a shutting-down replica frees its connection', async () => {
        const client = new RecordingRedisClient();
        await connection(client).close();

        expect(client.calls.map(call => call.command)).toEqual(['quit']);
    });
});

// ABOUTME: In-memory stand-ins for Redis: a store the handle registry can be driven against, a gate
// ABOUTME: that holds one replica's commands to force an interleaving, and a command-recording client.
import type { RedisClient } from '../../src/core/redis.js';
import type { RedisCommands } from '../../src/core/registry-redis.js';

export interface FakeRedisOptions {
    /** The clock TTLs are measured against, so a test can expire a key by moving time. */
    now?: (() => Date) | undefined;
}

/**
 * One instance stands for one Redis server.
 *
 * Two registries constructed over the same instance are two replicas sharing a store, which is
 * what the multi-replica behaviour needs to be tested against.
 */
export class FakeRedis implements RedisCommands {
    private readonly values = new Map<string, { value: string; expiresAtMs: number }>();
    private readonly sets = new Map<string, Set<string>>();

    constructor(private readonly options: FakeRedisOptions = {}) {}

    private nowMs(): number {
        return (this.options.now ?? (() => new Date()))().getTime();
    }

    private read(key: string): string | null {
        const entry = this.values.get(key);
        if (!entry) return null;
        if (entry.expiresAtMs <= this.nowMs()) {
            this.values.delete(key);
            return null;
        }
        return entry.value;
    }

    async get(key: string): Promise<string | null> {
        return this.read(key);
    }

    async set(key: string, value: string, ttlMs: number): Promise<void> {
        this.values.set(key, { value, expiresAtMs: this.nowMs() + ttlMs });
    }

    async setIfAbsent(key: string, value: string, ttlMs: number): Promise<boolean> {
        if (this.read(key) !== null) return false;
        this.values.set(key, { value, expiresAtMs: this.nowMs() + ttlMs });
        return true;
    }

    async compareSet(key: string, expected: string, value: string, ttlMs: number): Promise<boolean> {
        if (this.read(key) !== expected) return false;
        this.values.set(key, { value, expiresAtMs: this.nowMs() + ttlMs });
        return true;
    }

    async compareDelete(key: string, expected: string): Promise<boolean> {
        if (this.read(key) !== expected) return false;
        return this.values.delete(key);
    }

    async del(key: string): Promise<number> {
        return this.values.delete(key) ? 1 : 0;
    }

    /**
     * Redis INCR: a missing key counts as zero and is created with **no expiry**, and an increment
     * never touches the expiry of a key that already had one. Both matter — the first is why a
     * caller has to set a TTL itself, the second is why setting it every round is not a bug.
     */
    async incr(key: string): Promise<number> {
        const current = await this.get(key);
        if (current !== null && !/^-?\d+$/.test(current)) {
            throw new Error('ERR value is not an integer or out of range');
        }
        const next = (current === null ? 0 : Number.parseInt(current, 10)) + 1;
        const existing = this.values.get(key);
        this.values.set(key, {
            value: String(next),
            expiresAtMs: existing?.expiresAtMs ?? Number.POSITIVE_INFINITY,
        });
        return next;
    }

    /** Redis PEXPIRE: sets a millisecond TTL, and does nothing at all when the key is gone. */
    async pexpire(key: string, ttlMs: number): Promise<void> {
        const existing = this.values.get(key);
        if (!existing) return;
        existing.expiresAtMs = this.nowMs() + ttlMs;
    }

    async sadd(key: string, member: string): Promise<void> {
        const members = this.sets.get(key) ?? new Set<string>();
        members.add(member);
        this.sets.set(key, members);
    }

    async srem(key: string, member: string): Promise<void> {
        this.sets.get(key)?.delete(member);
    }

    async smembers(key: string): Promise<string[]> {
        return [...(this.sets.get(key) ?? [])];
    }

    /** Remaining TTL on a key, for asserting that a record outlives the session it points at. */
    ttlMs(key: string): number | undefined {
        const entry = this.values.get(key);
        return entry ? entry.expiresAtMs - this.nowMs() : undefined;
    }

    /** Every value key held, so a test can assert that a release left nothing behind. */
    valueKeys(): string[] {
        return [...this.values.keys()];
    }

    /** Every non-empty set and its members, for asserting that the indexes are swept too. */
    setMembers(): Record<string, string[]> {
        const entries = [...this.sets.entries()].filter(([, members]) => members.size > 0);
        return Object.fromEntries(entries.map(([key, members]) => [key, [...members]]));
    }
}

/**
 * Delays one replica's commands so a test can pin down the order two replicas run in.
 *
 * It adds no semantics of its own — every command is forwarded to the store unchanged — so what a
 * test built on it observes is the store behaving normally under an interleaving that is otherwise
 * a matter of timing. That is the only way to assert on a race deterministically.
 */
export class GatedRedis implements RedisCommands {
    private gate: Promise<void> | undefined;
    private open: (() => void) | undefined;
    private passesLeft = 0;

    constructor(private readonly inner: RedisCommands) {}

    /**
     * Holds commands issued from now on, until `release`.
     *
     * `passes` commands go through first, which is how an operation is caught mid-flight rather
     * than before it starts: holding a read only makes it happen later, and therefore see fresher
     * data, whereas letting the read through and holding the write is what makes the write stale.
     */
    hold(passes = 0): void {
        this.passesLeft = passes;
        this.gate = new Promise<void>(resolve => {
            this.open = resolve;
        });
    }

    /** Lets the held commands through, and stops holding new ones. */
    release(): void {
        this.open?.();
        this.gate = undefined;
        this.open = undefined;
        this.passesLeft = 0;
    }

    private async gated<T>(run: () => Promise<T>): Promise<T> {
        if (this.passesLeft > 0) {
            this.passesLeft -= 1;
            return run();
        }
        await this.gate;
        return run();
    }

    async get(key: string): Promise<string | null> {
        return this.gated(() => this.inner.get(key));
    }

    async set(key: string, value: string, ttlMs: number): Promise<void> {
        return this.gated(() => this.inner.set(key, value, ttlMs));
    }

    async setIfAbsent(key: string, value: string, ttlMs: number): Promise<boolean> {
        return this.gated(() => this.inner.setIfAbsent(key, value, ttlMs));
    }

    async compareSet(key: string, expected: string, value: string, ttlMs: number): Promise<boolean> {
        return this.gated(() => this.inner.compareSet(key, expected, value, ttlMs));
    }

    async compareDelete(key: string, expected: string): Promise<boolean> {
        return this.gated(() => this.inner.compareDelete(key, expected));
    }

    async del(key: string): Promise<number> {
        return this.gated(() => this.inner.del(key));
    }

    async incr(key: string): Promise<number> {
        return this.gated(() => this.inner.incr(key));
    }

    async pexpire(key: string, ttlMs: number): Promise<void> {
        return this.gated(() => this.inner.pexpire(key, ttlMs));
    }

    async sadd(key: string, member: string): Promise<void> {
        return this.gated(() => this.inner.sadd(key, member));
    }

    async srem(key: string, member: string): Promise<void> {
        return this.gated(() => this.inner.srem(key, member));
    }

    async smembers(key: string): Promise<string[]> {
        return this.gated(() => this.inner.smembers(key));
    }
}

export interface RecordingRedisClientReplies {
    get?: string | null;
    del?: number;
    incr?: number;
    smembers?: string[];
    set?: unknown;
    eval?: unknown;
}

/** Records the calls the ioredis adapter makes, so argument shapes can be asserted without a server. */
export class RecordingRedisClient implements RedisClient {
    readonly calls: Array<{ command: string; args: unknown[] }> = [];
    private readonly errorListeners: Array<(error: Error) => void> = [];

    constructor(private readonly replies: RecordingRedisClientReplies = {}) {}

    private record(command: string, args: unknown[]): void {
        this.calls.push({ command, args });
    }

    async get(key: string): Promise<string | null> {
        this.record('get', [key]);
        return this.replies.get ?? null;
    }

    async set(key: string, value: string, mode: 'PX', ttlMs: number, condition?: 'NX'): Promise<unknown> {
        this.record('set', condition ? [key, value, mode, ttlMs, condition] : [key, value, mode, ttlMs]);
        return this.replies.set ?? 'OK';
    }

    async eval(script: string, numberOfKeys: number, ...args: Array<string | number>): Promise<unknown> {
        this.record('eval', [script, numberOfKeys, ...args]);
        return this.replies.eval ?? 1;
    }

    async del(key: string): Promise<number> {
        this.record('del', [key]);
        return this.replies.del ?? 0;
    }

    async incr(key: string): Promise<number> {
        this.record('incr', [key]);
        return this.replies.incr ?? 1;
    }

    async pexpire(key: string, ttlMs: number): Promise<number> {
        this.record('pexpire', [key, ttlMs]);
        return 1;
    }

    async sadd(key: string, member: string): Promise<number> {
        this.record('sadd', [key, member]);
        return 1;
    }

    async srem(key: string, member: string): Promise<number> {
        this.record('srem', [key, member]);
        return 1;
    }

    async smembers(key: string): Promise<string[]> {
        this.record('smembers', [key]);
        return this.replies.smembers ?? [];
    }

    async quit(): Promise<unknown> {
        this.record('quit', []);
        return 'OK';
    }

    on(event: 'error', listener: (error: Error) => void): this {
        if (event === 'error') this.errorListeners.push(listener);
        return this;
    }

    /** Stands in for the reconnect failures a real client emits at any time. */
    emitError(error: Error): void {
        for (const listener of this.errorListeners) listener(error);
    }
}

// ABOUTME: Unit tests for the Redis-backed handle registry: the same state machine as the in-memory
// ABOUTME: backend, plus the multi-replica behaviour a shared store adds — handoff and concurrent reaps.
import { describe, expect, it, vi } from 'vitest';
import { SteelToolError } from '../../src/core/errors.js';
import { principalFromCredential, type RegistryDeps } from '../../src/core/registry.js';
import { RedisHandleRegistry } from '../../src/core/registry-redis.js';
import { FakeRedis, GatedRedis } from '../helpers/fake-redis.js';

const ORG_A = principalFromCredential('ste-key-a');
const ORG_B = principalFromCredential('ste-key-b');

/** A movable clock in the `() => Date` shape the rest of the server injects. */
function testClock(startMs = 1_800_000_000_000) {
    let ms = startMs;
    return {
        now: () => new Date(ms),
        advance: (deltaMs: number) => {
            ms += deltaMs;
        },
        get ms() {
            return ms;
        },
    };
}

interface HarnessOptions {
    store?: FakeRedis;
    clock?: ReturnType<typeof testClock>;
    releaseSteelSession?: RegistryDeps['releaseSteelSession'];
    onReapError?: RegistryDeps['onReapError'];
}

/** Builds one replica. Pass the same store and clock twice to model two replicas of one deployment. */
function harness(options: HarnessOptions = {}) {
    const clock = options.clock ?? testClock();
    const store = options.store ?? new FakeRedis({ now: clock.now });
    const released: string[] = [];
    const registry = new RedisHandleRegistry({
        commands: store,
        now: clock.now,
        releaseSteelSession:
            options.releaseSteelSession ??
            (async (id: string) => {
                released.push(id);
            }),
        onReapError: options.onReapError,
    });
    return { registry, store, clock, released };
}

async function captureError(promise: Promise<unknown>): Promise<SteelToolError> {
    try {
        await promise;
    } catch (error) {
        return error as SteelToolError;
    }
    throw new Error('Expected the promise to reject, but it resolved.');
}

describe('RedisHandleRegistry.create', () => {
    it('mints an opaque prefixed handle with at least 128 bits of entropy', async () => {
        const { registry, clock } = harness();
        const record = await registry.create({
            principal: ORG_A,
            steelSessionId: 'steel-1',
            expiresAt: clock.ms + 60_000,
        });
        expect(record.handle.startsWith('sess_')).toBe(true);
        expect(record.handle.length - 'sess_'.length).toBeGreaterThanOrEqual(22);
    });

    it('never derives the handle from the principal or the Steel id', async () => {
        const { registry, clock } = harness();
        const handles = new Set<string>();
        for (let i = 0; i < 50; i++) {
            const record = await registry.create({
                principal: ORG_A,
                steelSessionId: 'steel-1',
                expiresAt: clock.ms + 60_000,
            });
            expect(record.handle).not.toContain(ORG_A);
            expect(record.handle).not.toContain('steel-1');
            handles.add(record.handle);
        }
        expect(handles.size).toBe(50);
    });

    it('stores the record under a key namespaced by prefix and principal', async () => {
        const clock = testClock();
        const store = new FakeRedis({ now: clock.now });
        const registry = new RedisHandleRegistry({
            commands: store,
            keyPrefix: 'tenant-x',
            now: clock.now,
            releaseSteelSession: async () => {},
        });
        const record = await registry.create({
            principal: ORG_A,
            steelSessionId: 'steel-1',
            expiresAt: clock.ms + 60_000,
        });

        expect(store.valueKeys()).toEqual([`tenant-x:handle:${record.handle}`]);
        expect(store.setMembers()[`tenant-x:principal:${ORG_A}`]).toEqual([record.handle]);
        expect(store.setMembers()['tenant-x:live']).toEqual([`${ORG_A}:${record.handle}`]);
    });

    it('keeps the record alive well past the hard expiry, so a failed release can still be retried', async () => {
        const { registry, store, clock } = harness();
        const expiresIn = 60_000;
        await registry.create({
            principal: ORG_A,
            steelSessionId: 'steel-1',
            expiresAt: clock.ms + expiresIn,
        });

        const [key] = store.valueKeys();
        expect(store.ttlMs(key!)).toBeGreaterThan(expiresIn);
    });

    it('still gives a long-expired handle a positive expiry, which is the only kind Redis accepts', async () => {
        const { registry, store, clock } = harness();
        await registry.create({
            principal: ORG_A,
            steelSessionId: 'steel-1',
            expiresAt: clock.ms - 30 * 86_400_000,
        });

        const [key] = store.valueKeys();
        expect(store.ttlMs(key!)).toBeGreaterThan(0);
    });
});

describe('RedisHandleRegistry human control', () => {
    it('shares an exclusive fencing lease across replicas', async () => {
        const clock = testClock();
        const store = new FakeRedis({ now: clock.now });
        const first = harness({ clock, store }).registry;
        const second = harness({ clock, store }).registry;
        const { handle } = await first.create({
            principal: ORG_A,
            steelSessionId: 's1',
            expiresAt: clock.ms + 600_000,
        });

        const lease = await first.acquireHumanControl(handle, ORG_A, 60_000);
        await expect(second.acquireHumanControl(handle, ORG_A, 60_000)).rejects.toMatchObject({
            code: 'human_control_active',
        });
        await expect(second.resolveForAgent(handle, ORG_A)).rejects.toMatchObject({
            code: 'human_control_active',
        });
        const renewed = await second.renewHumanControl(handle, ORG_A, lease.token, 60_000);
        await second.releaseHumanControl(handle, ORG_A, renewed.token);
        await expect(first.resolveForAgent(handle, ORG_A)).resolves.toMatchObject({ handle });
    });

    it('lets an expired viewer lease disappear without a cleanup call', async () => {
        const { registry, clock } = harness();
        const { handle } = await registry.create({
            principal: ORG_A,
            steelSessionId: 's1',
            expiresAt: clock.ms + 600_000,
        });
        await registry.acquireHumanControl(handle, ORG_A, 60_000);
        clock.advance(60_001);
        await expect(registry.resolveForAgent(handle, ORG_A)).resolves.toMatchObject({ handle });
    });

    it('shares the release fence before an external release completes', async () => {
        const clock = testClock();
        const store = new FakeRedis({ now: clock.now });
        let finish!: () => void;
        let started!: () => void;
        const releasing = new Promise<void>(resolve => (started = resolve));
        const gate = new Promise<void>(resolve => (finish = resolve));
        const first = harness({
            clock,
            store,
            releaseSteelSession: async () => {
                started();
                await gate;
            },
        }).registry;
        const second = harness({ clock, store }).registry;
        const { handle } = await first.create({
            principal: ORG_A,
            steelSessionId: 's1',
            expiresAt: clock.ms + 600_000,
        });

        const pending = first.release(handle, ORG_A, 'explicit');
        await releasing;
        await expect(second.resolveForAgent(handle, ORG_A)).rejects.toMatchObject({ code: 'session_releasing' });
        await expect(second.acquireHumanControl(handle, ORG_A, 60_000)).rejects.toMatchObject({
            code: 'session_releasing',
        });
        finish();
        await pending;
    });
});

describe('RedisHandleRegistry.resolve', () => {
    it('returns the record for the principal that created it', async () => {
        const { registry, clock } = harness();
        const { handle } = await registry.create({
            principal: ORG_A,
            steelSessionId: 'steel-1',
            expiresAt: clock.ms + 60_000,
            viewerUrl: 'https://app.steel.dev/sessions/steel-1',
            mitigation: { useProxy: true },
        });

        await expect(registry.resolve(handle, ORG_A)).resolves.toMatchObject({
            steelSessionId: 'steel-1',
            principal: ORG_A,
            viewerUrl: 'https://app.steel.dev/sessions/steel-1',
            mitigation: { useProxy: true },
        });
    });

    it('rejects a handle presented by a different principal', async () => {
        const { registry, clock } = harness();
        const { handle } = await registry.create({
            principal: ORG_A,
            steelSessionId: 'steel-1',
            expiresAt: clock.ms + 60_000,
        });

        const error = await captureError(registry.resolve(handle, ORG_B));
        expect(error).toBeInstanceOf(SteelToolError);
        expect(error.code).toBe('not_found');
    });

    it('does not reveal whether a rejected handle exists', async () => {
        const { registry, clock } = harness();
        const { handle } = await registry.create({
            principal: ORG_A,
            steelSessionId: 'steel-1',
            expiresAt: clock.ms + 60_000,
        });

        const wrongOrg = await registry.resolve(handle, ORG_B).catch(e => (e as Error).message);
        const unknown = await registry.resolve('sess_nope', ORG_B).catch(e => (e as Error).message);
        expect(wrongOrg).toBe(unknown);
    });

    it('rejects an expired handle with its own code', async () => {
        const { registry, clock } = harness();
        const { handle } = await registry.create({
            principal: ORG_A,
            steelSessionId: 'steel-1',
            expiresAt: clock.ms + 1_000,
        });

        clock.advance(2_000);
        const error = await captureError(registry.resolve(handle, ORG_A));
        expect(error.code).toBe('session_expired');
    });

    it('treats an unreadable record as an unknown handle rather than throwing a parse error', async () => {
        const { registry, store, clock } = harness();
        const { handle } = await registry.create({
            principal: ORG_A,
            steelSessionId: 'steel-1',
            expiresAt: clock.ms + 60_000,
        });
        const [key] = store.valueKeys();
        await store.set(key!, 'not json', 60_000);

        const error = await captureError(registry.resolve(handle, ORG_A));
        expect(error.code).toBe('not_found');
    });
});

describe('RedisHandleRegistry.touch', () => {
    it('records the last use so the reaper can measure idleness', async () => {
        const { registry, clock } = harness();
        const { handle } = await registry.create({
            principal: ORG_A,
            steelSessionId: 'steel-1',
            expiresAt: clock.ms + 600_000,
        });

        const before = (await registry.resolve(handle, ORG_A)).lastUsedAt;
        clock.advance(5_000);
        await registry.touch(handle);

        expect((await registry.resolve(handle, ORG_A)).lastUsedAt).toBe(before + 5_000);
    });

    it('ignores an unknown handle', async () => {
        const { registry } = harness();
        await expect(registry.touch('sess_nope')).resolves.toBeUndefined();
    });
});

describe('RedisHandleRegistry.release', () => {
    it.each([
        ['explicit', 'capacity'],
        ['explicit', 'profile-writer'],
        ['reap', 'capacity'],
        ['reap', 'profile-writer'],
    ] as const)('retains retryable records when %s cleanup fails in %s', async (path, ledger) => {
        const errors: unknown[] = [];
        const { registry, store, clock } = harness({ onReapError: error => errors.push(error) });
        const until = clock.ms + 60_000;
        await registry.reserveSessionSlot(ORG_A, 'steel-1', until, 1);
        await registry.reserveProfileWriter(ORG_A, 'profile-1', 'steel-1', until);
        const { handle } = await registry.create({
            principal: ORG_A,
            steelSessionId: 'steel-1',
            expiresAt: until,
            mitigation: { persistProfile: true, profileId: 'profile-1' },
        });
        const original = store.compareDelete.bind(store);
        let fail = true;
        vi.spyOn(store, 'compareDelete').mockImplementation(async (key, expected) => {
            if (fail && key.includes(`:${ledger}:`)) {
                fail = false;
                throw new Error('transient ledger failure');
            }
            return original(key, expected);
        });

        if (path === 'explicit') {
            await expect(registry.release(handle, ORG_A, 'explicit')).rejects.toThrow('transient ledger failure');
        } else {
            expect(await registry.reap({ idleMs: 0 })).toBe(0);
            expect(errors).toHaveLength(1);
        }
        const remaining = await registry.list(ORG_A);
        expect(remaining).toHaveLength(1);
        expect(remaining[0]?.releasing).toBeFalsy();
        expect(registry.releaseCounts()).toEqual({ explicit: 0, stream_close: 0, idle: 0, hard_expiry: 0 });

        // A different replica can finish immediately, without waiting for either ledger's TTL.
        const retry = harness({ store, clock }).registry;
        expect(await retry.reap({ idleMs: 0 })).toBe(1);
        expect(retry.releaseCounts().idle).toBe(1);
        expect(await retry.list(ORG_A)).toEqual([]);
        expect(store.valueKeys()).toEqual([]);
        expect(store.setMembers()).toEqual({});
        expect(await retry.reserveSessionSlot(ORG_A, 'steel-2', until, 1)).toBe(true);
        expect(await retry.reserveProfileWriter(ORG_A, 'profile-1', 'steel-2', until)).toBe(true);
    });

    it('releases the Steel session and forgets the handle, indexes included', async () => {
        const { registry, store, clock, released } = harness();
        const { handle } = await registry.create({
            principal: ORG_A,
            steelSessionId: 'steel-1',
            expiresAt: clock.ms + 60_000,
        });

        const record = await registry.release(handle, ORG_A, 'explicit');
        expect(record?.steelSessionId).toBe('steel-1');
        expect(released).toEqual(['steel-1']);
        expect(await registry.countLive(ORG_A)).toBe(0);
        expect(store.valueKeys()).toEqual([]);
        expect(store.setMembers()).toEqual({});
    });

    it('names the owning principal, so a hosted replica can pick the credential allowed to release', async () => {
        const releases: Array<[string, string]> = [];
        const clock = testClock();
        const registry = new RedisHandleRegistry({
            commands: new FakeRedis({ now: clock.now }),
            now: clock.now,
            releaseSteelSession: async (id: string, principal: string) => {
                releases.push([id, principal]);
            },
        });
        const { handle } = await registry.create({
            principal: ORG_A,
            steelSessionId: 'steel-1',
            expiresAt: clock.ms + 60_000,
        });

        await registry.release(handle, ORG_A, 'explicit');
        expect(releases).toEqual([['steel-1', ORG_A]]);
    });

    it('is idempotent: a second release neither throws nor re-releases', async () => {
        const { registry, clock, released } = harness();
        const { handle } = await registry.create({
            principal: ORG_A,
            steelSessionId: 'steel-1',
            expiresAt: clock.ms + 60_000,
        });

        await registry.release(handle, ORG_A, 'explicit');
        await expect(registry.release(handle, ORG_A, 'explicit')).resolves.toBeNull();
        expect(released).toEqual(['steel-1']);
        expect(registry.releaseCounts().explicit).toBe(1);
    });

    it('refuses to release another principal handle', async () => {
        const { registry, clock, released } = harness();
        const { handle } = await registry.create({
            principal: ORG_A,
            steelSessionId: 'steel-1',
            expiresAt: clock.ms + 60_000,
        });

        await expect(registry.release(handle, ORG_B, 'explicit')).rejects.toBeInstanceOf(SteelToolError);
        expect(released).toEqual([]);
        expect(await registry.countLive(ORG_A)).toBe(1);
    });

    it('releases the Steel session before forgetting the handle', async () => {
        // If the record went first, a transient failure would lose it: no retry, the reaper could
        // never see it, and the browser would bill on with nothing tracking it.
        let resolvableDuringRelease: boolean | undefined;
        const clock = testClock();
        const store = new FakeRedis({ now: clock.now });
        const registry: RedisHandleRegistry = new RedisHandleRegistry({
            commands: store,
            now: clock.now,
            releaseSteelSession: async () => {
                resolvableDuringRelease = await registry
                    .resolve(handle, ORG_A)
                    .then(() => true)
                    .catch(() => false);
            },
        });
        const { handle } = await registry.create({
            principal: ORG_A,
            steelSessionId: 's1',
            expiresAt: clock.ms + 60_000,
        });

        await registry.release(handle, ORG_A, 'explicit');
        expect(resolvableDuringRelease, 'the record was deleted before the release was awaited').toBe(true);
    });

    it('keeps the handle when the Steel release fails, so the reaper can retry', async () => {
        let attempts = 0;
        const { registry, clock } = harness({
            releaseSteelSession: async () => {
                attempts += 1;
                if (attempts === 1) throw new Error('steel unreachable');
            },
        });
        const { handle } = await registry.create({
            principal: ORG_A,
            steelSessionId: 's1',
            expiresAt: clock.ms + 60_000,
        });

        await expect(registry.release(handle, ORG_A, 'explicit')).rejects.toThrow(/steel unreachable/);
        expect(await registry.countLive(ORG_A), 'the handle was dropped despite the failure').toBe(1);
        expect(registry.releaseCounts().explicit, 'the leak metric counted a release that never happened').toBe(0);

        await expect(registry.release(handle, ORG_A, 'explicit')).resolves.toBeTruthy();
        expect(await registry.countLive(ORG_A)).toBe(0);
        expect(registry.releaseCounts().explicit).toBe(1);
    });
});

describe('RedisHandleRegistry.reap', () => {
    it('releases handles idle past the deadline and leaves fresh ones alone', async () => {
        const { registry, clock, released } = harness();
        const stale = await registry.create({
            principal: ORG_A,
