describe('RedisHandleRegistry.recordHandoff', () => {
    it('gives the counter an expiry, which an increment on its own would not', async () => {
        // INCR creates its key with no TTL at all, so without the explicit expiry the counter for
        // every handle a deployment ever mints would sit in Redis for good.
        const { registry, store, clock } = harness();
        const { handle } = await registry.create({
            principal: ORG_A,
            steelSessionId: 'steel-1',
            expiresAt: clock.ms + 600_000,
        });

        await registry.recordHandoff(handle);

        const ttl = store.ttlMs(`steel-mcp:handle:${handle}:rounds`);
        expect(ttl, 'the counter key was never given an expiry').toBeLessThan(Number.POSITIVE_INFINITY);
        expect(ttl).toBeGreaterThan(0);
    });

    it('is swept with the handle, so a released session leaves no counter behind', async () => {
        const { registry, store, clock } = harness();
        const { handle } = await registry.create({
            principal: ORG_A,
            steelSessionId: 'steel-1',
            expiresAt: clock.ms + 600_000,
        });
        await registry.recordHandoff(handle);

        await registry.release(handle, ORG_A, 'explicit');
        expect(store.valueKeys()).toEqual([]);
    });
});

describe('RedisHandleRegistry across replicas', () => {
    /** Two registries over one store: exactly the hosted shape, where no request is routed stickily. */
    function twoReplicas(options: HarnessOptions = {}) {
        const clock = options.clock ?? testClock();
        const store = options.store ?? new FakeRedis({ now: clock.now });
        const first = harness({ ...options, store, clock });
        const second = harness({ ...options, store, clock });
        return { first, second, store, clock };
    }

    it('resolves on a second replica a handle the first one created', async () => {
        const { first, second, clock } = twoReplicas();
        const { handle } = await first.registry.create({
            principal: ORG_A,
            steelSessionId: 'steel-1',
            expiresAt: clock.ms + 60_000,
        });

        await expect(second.registry.resolve(handle, ORG_A)).resolves.toMatchObject({ steelSessionId: 'steel-1' });
        expect(await second.registry.countLive(ORG_A)).toBe(1);
    });

    it('keeps a handle opaque to another principal on every replica', async () => {
        const { first, second, clock } = twoReplicas();
        const { handle } = await first.registry.create({
            principal: ORG_A,
            steelSessionId: 'steel-1',
            expiresAt: clock.ms + 60_000,
        });

        const error = await captureError(second.registry.resolve(handle, ORG_B));
        expect(error.code).toBe('not_found');
        expect(await second.registry.countLive(ORG_B)).toBe(0);
    });

    it('counts handoff rounds as one sequence however the calls are routed', async () => {
        // The bound is per handle, not per replica. A per-process count would restart on whichever
        // replica had not seen the handle, and a person would be interrupted again for free.
        const { first, second, clock } = twoReplicas();
        const { handle } = await first.registry.create({
            principal: ORG_A,
            steelSessionId: 'steel-1',
            expiresAt: clock.ms + 900_000,
        });

        expect(await first.registry.recordHandoff(handle)).toBe(1);
        expect(await second.registry.recordHandoff(handle), 'the second replica started its own count').toBe(2);
        expect(await first.registry.recordHandoff(handle)).toBe(3);

        // Whichever replica serves the next retry reads the same total and stops offering.
        expect((await first.registry.resolve(handle, ORG_A)).handoffRounds).toBe(3);
        expect((await second.registry.resolve(handle, ORG_A)).handoffRounds).toBe(3);
    });

    it('carries a touch on one replica over to the other replica idle math', async () => {
        const { first, second, clock } = twoReplicas();
        const { handle } = await first.registry.create({
            principal: ORG_A,
            steelSessionId: 'steel-1',
            expiresAt: clock.ms + 600_000,
        });

        clock.advance(100_000);
        await second.registry.touch(handle);
        clock.advance(60_000);

        expect(await first.registry.reap({ idleMs: 120_000 }), 'a touch on another replica was not seen').toBe(0);
    });

    it('is idempotent across replicas: releasing on one leaves nothing for the other', async () => {
        const { first, second, clock } = twoReplicas();
        const { handle } = await first.registry.create({
            principal: ORG_A,
            steelSessionId: 'steel-1',
            expiresAt: clock.ms + 60_000,
        });

        await first.registry.release(handle, ORG_A, 'explicit');
        await expect(second.registry.release(handle, ORG_A, 'explicit')).resolves.toBeNull();
        expect(first.released).toEqual(['steel-1']);
        expect(second.released, 'the second replica released a session the first had already released').toEqual([]);
    });

    it('does not let a touch already in flight put back a handle another replica released', async () => {
        // A resurrected record is worse than a leaked key: `release` has already removed both index
        // entries, so nothing lists it and no sweep on any replica will ever visit it again, while
        // it keeps resolving as a live handle whose browser Steel has already torn down.
        const clock = testClock();
        const store = new FakeRedis({ now: clock.now });
        const gated = new GatedRedis(store);
        const releasing = harness({ store, clock });
        const touching = new RedisHandleRegistry({
            commands: gated,
            now: clock.now,
            releaseSteelSession: async () => {},
        });
        const { handle } = await releasing.registry.create({
            principal: ORG_A,
            steelSessionId: 'steel-1',
            expiresAt: clock.ms + 600_000,
        });

        // The touch sees a live handle, and is caught before it has finished writing.
        gated.hold(1);
        const pending = touching.touch(handle);
        expect(await releasing.registry.release(handle, ORG_A, 'explicit')).toBeTruthy();
        gated.release();
        await pending;

        const error = await captureError(releasing.registry.resolve(handle, ORG_A));
        expect(error.code, 'the released handle resolved again').toBe('not_found');
        expect(await releasing.registry.list(ORG_A)).toEqual([]);
        expect(await releasing.registry.reap({ idleMs: 0 })).toBe(0);
        expect(releasing.released, 'the session was released twice').toEqual(['steel-1']);
        // Nothing that could be read back as a handle survives: the release swept the last-use key
        // the touch had already written, and one written after a sweep expires on its own.
        expect(store.valueKeys()).not.toContain(`steel-mcp:handle:${handle}`);
    });

    it('counts one release when two replicas sweep the same handle at once', async () => {
        // Atomic SET-NX release fencing admits one sweep; the loser neither releases nor counts.
        const { first, second, store, clock } = twoReplicas();
        await first.registry.create({ principal: ORG_A, steelSessionId: 'steel-1', expiresAt: clock.ms + 600_000 });
        clock.advance(200_000);

        const [reapedByFirst, reapedBySecond] = await Promise.all([
            first.registry.reap({ idleMs: 120_000 }),
            second.registry.reap({ idleMs: 120_000 }),
        ]);

        expect([...first.released, ...second.released]).toEqual(['steel-1']);
        expect(reapedByFirst + reapedBySecond, 'the same handle was reaped twice').toBe(1);
        const counts = first.registry.releaseCounts().idle + second.registry.releaseCounts().idle;
        expect(counts, 'two replicas both counted the one release').toBe(1);
        expect(store.valueKeys()).toEqual([]);
        expect(store.setMembers()).toEqual({});
        expect(await first.registry.countLive(ORG_A)).toBe(0);
    });

    it('leaves nothing behind when every replica sweeps a whole store', async () => {
        const { first, second, store, clock } = twoReplicas();
        for (const id of ['s1', 's2', 's3']) {
            await first.registry.create({ principal: ORG_A, steelSessionId: id, expiresAt: clock.ms + 600_000 });
        }
        await second.registry.create({ principal: ORG_B, steelSessionId: 's4', expiresAt: clock.ms + 600_000 });
        clock.advance(200_000);

        const swept = await Promise.all([
            first.registry.reap({ idleMs: 120_000 }),
            second.registry.reap({ idleMs: 120_000 }),
        ]);

        // Every session is released, each counted exactly once across the fleet. A replica may ask
        // Steel to release a session another replica had already released; that call is idempotent,
        // which is why concurrent sweeps need no coordination.
        expect(swept[0] + swept[1]).toBe(4);
        expect([...new Set([...first.released, ...second.released])].sort()).toEqual(['s1', 's2', 's3', 's4']);
        expect(first.registry.releaseCounts().idle + second.registry.releaseCounts().idle).toBe(4);
        expect(store.valueKeys()).toEqual([]);
        expect(store.setMembers()).toEqual({});
    });
});

describe('RedisHandleRegistry.awaitInput', () => {
    it('suspends idle reclamation while a person finishes a step in the live session', async () => {
        const { registry, clock, released } = harness();
        const { handle } = await registry.create({
            principal: ORG_A,
            steelSessionId: 'steel-1',
            expiresAt: clock.ms + 600_000,
        });
        await registry.awaitInput(handle, clock.ms + 300_000);
        clock.advance(200_000);

        expect(await registry.reap({ idleMs: 120_000 })).toBe(0);
        expect(released).toEqual([]);
    });

    it('still reaps a handle awaiting human input once its hard expiry passes', async () => {
        // The grace window suspends our slot reclamation only. The hard timeout is Steel's, and
        // nothing about a pending elicitation may extend it.
        const { registry, clock, released } = harness();
        const { handle } = await registry.create({
            principal: ORG_A,
            steelSessionId: 'steel-1',
            expiresAt: clock.ms + 1_000,
        });
        await registry.awaitInput(handle, clock.ms + 600_000);
        clock.advance(2_000);

        expect(await registry.reap({ idleMs: 120_000 })).toBe(1);
        expect(released).toEqual(['steel-1']);
    });

    it('reaps a handle again once its grace window lapses, so a walked-away human frees the slot', async () => {
        const { registry, clock, released } = harness();
        const { handle } = await registry.create({
            principal: ORG_A,
            steelSessionId: 'steel-1',
            expiresAt: clock.ms + 900_000,
        });
        await registry.awaitInput(handle, clock.ms + 60_000);
        clock.advance(120_000);

        expect(await registry.reap({ idleMs: 90_000 })).toBe(1);
        expect(released).toEqual(['steel-1']);
    });

    it('clears the grace window on the next real call, so normal idle accounting resumes', async () => {
        const { registry, clock, released } = harness();
        const { handle } = await registry.create({
            principal: ORG_A,
            steelSessionId: 'steel-1',
            expiresAt: clock.ms + 900_000,
        });
        await registry.awaitInput(handle, clock.ms + 600_000);
        await registry.touch(handle);
        clock.advance(200_000);

        expect(await registry.reap({ idleMs: 120_000 })).toBe(1);
        expect(released).toEqual(['steel-1']);
    });

    it('does not roll back a touch that landed while the handoff was being registered', async () => {
        // The write that lost this update was a whole-record rewrite built from a read taken before
        // the touch. Both operations now write only the one key they own, so neither can undo the
        // other, and the order they settle in stops mattering.
        const clock = testClock();
        const store = new FakeRedis({ now: clock.now });
        const gated = new GatedRedis(store);
        const touching = harness({ store, clock });
        const awaiting = new RedisHandleRegistry({
            commands: gated,
            now: clock.now,
            releaseSteelSession: async () => {},
        });
        const { handle } = await touching.registry.create({
            principal: ORG_A,
            steelSessionId: 'steel-1',
            expiresAt: clock.ms + 900_000,
        });

        clock.advance(100_000);
        // Whatever the handoff reads, it reads before the touch; whatever it writes, it writes after.
        gated.hold(1);
        const pending = awaiting.awaitInput(handle, clock.ms + 60_000);
        await touching.registry.touch(handle);
        const touchedAt = clock.ms;
        gated.release();
        await pending;

        const record = await touching.registry.resolve(handle, ORG_A);
        expect(record.lastUsedAt, 'the handoff write rolled the last use back to before the touch').toBe(touchedAt);

        // The consequence of that rollback: idleness measured from the older timestamp reclaims the
        // slot while the session is in active use.
        clock.advance(90_000);
        expect(await touching.registry.reap({ idleMs: 120_000 })).toBe(0);
        expect(touching.released).toEqual([]);
    });

    it('defers the other replica reaper too, because the mark lives in the shared record', async () => {
        const clock = testClock();
        const store = new FakeRedis({ now: clock.now });
        const first = harness({ store, clock });
        const second = harness({ store, clock });
        const { handle } = await first.registry.create({
            principal: ORG_A,
            steelSessionId: 'steel-1',
            expiresAt: clock.ms + 600_000,
        });
        await first.registry.awaitInput(handle, clock.ms + 300_000);
        clock.advance(200_000);

        expect(await second.registry.reap({ idleMs: 120_000 })).toBe(0);
        expect(second.released).toEqual([]);
    });
});

// ABOUTME: Unit tests for the cost-weighted rate limiter: the weight table, per-principal isolation,
// ABOUTME: refill on the injected clock, and the rejection error naming the limit and a retry-after.
import { describe, expect, it } from 'vitest';
import { SteelToolError, toolErrorResult } from '../../src/core/errors.js';
import {
    DEFAULT_RATE_LIMIT_POLICY,
    DEFAULT_TOOL_COST,
    InMemoryRateLimiter,
    RATE_LIMIT_NAME,
    type RateLimitPolicy,
    TOOL_COSTS,
    toolCost,
} from '../../src/core/rate-limit.js';

/** One unit per second, ten units of burst: every refill in these tests lands on an exact integer. */
const TEST_POLICY: RateLimitPolicy = { refillPerMinute: 60, burstCapacity: 10 };

function clock(startMs = 1_800_000_000_000) {
    let ms = startMs;
    return {
        now: () => new Date(ms),
        advanceSeconds: (seconds: number) => {
            ms += seconds * 1_000;
        },
    };
}

function limiter(policy: RateLimitPolicy = TEST_POLICY) {
    const time = clock();
    return { limiter: new InMemoryRateLimiter({ policy, now: time.now }), time };
}

async function rejection(work: () => Promise<unknown>): Promise<SteelToolError> {
    try {
        await work();
    } catch (error) {
        if (error instanceof SteelToolError) return error;
        throw error;
    }
    throw new Error('Expected the limiter to reject this call.');
}

describe('the tool weight table', () => {
    it('charges session-creating and CDP-driving tools more than the stateless reads', () => {
        const stateless = Math.max(toolCost('steel_scrape'), toolCost('steel_screenshot'), toolCost('steel_pdf'));
        for (const tool of ['steel_session_create', 'steel_navigate', 'steel_act', 'steel_snapshot', 'steel_batch']) {
            expect(toolCost(tool), `${tool} must cost more than a stateless read`).toBeGreaterThan(stateless);
        }
        expect(toolCost('steel_session_create')).toBe(Math.max(...Object.values(TOOL_COSTS)));
    });

    it('never charges for handing a concurrency slot back', () => {
        expect(toolCost('steel_session_release')).toBe(0);
    });

    it('does not charge app control heartbeats against the model budget', () => {
        expect(toolCost('steel_session_live_view')).toBe(0);
        expect(toolCost('steel_session_live_view')).toBeLessThan(toolCost('steel_navigate'));
    });

    it('charges a handoff like a stateless coordination call', () => {
        expect(toolCost('steel_session_handoff')).toBe(toolCost('steel_scrape'));
    });

    it('charges finished replay like a stateless read, since it starts no browser', () => {
        expect(toolCost('steel_session_replay')).toBe(toolCost('steel_scrape'));
        expect(toolCost('steel_session_replay')).toBeLessThan(toolCost('steel_navigate'));
    });

    it('charges an unlisted tool the session-driving default rather than nothing', () => {
        expect(toolCost('steel_tool_added_later')).toBe(DEFAULT_TOOL_COST);
        expect(DEFAULT_TOOL_COST).toBeGreaterThan(0);
    });

    it('sizes the shipped budget so stateless reads track the 20/min Browser Tools cap', () => {
        expect(DEFAULT_RATE_LIMIT_POLICY.refillPerMinute).toBe(20);
        expect(toolCost('steel_scrape')).toBe(1);
        expect(DEFAULT_RATE_LIMIT_POLICY.burstCapacity).toBeGreaterThan(DEFAULT_RATE_LIMIT_POLICY.refillPerMinute);
    });
});

describe('cost-weighted accounting', () => {
    it('spends the bucket in proportion to the weight of each tool', async () => {
        const { limiter: rate } = limiter();

        // Ten one-unit reads exactly drain a ten-unit bucket.
        for (let call = 0; call < 10; call++) await rate.charge('principal-a', 'steel_scrape');
        await expect(rate.charge('principal-a', 'steel_scrape')).rejects.toThrow(/budget/);

        // A single heavier call drains the same bucket for another principal.
        const { limiter: heavier } = limiter();
        await heavier.charge('principal-b', 'steel_batch');
        const left = TEST_POLICY.burstCapacity - toolCost('steel_batch');
        for (let call = 0; call < left; call++) await heavier.charge('principal-b', 'steel_scrape');
        await expect(heavier.charge('principal-b', 'steel_scrape')).rejects.toThrow(/budget/);
    });

    it('still admits a release once the budget is exhausted', async () => {
        const { limiter: rate } = limiter();
        for (let call = 0; call < 10; call++) await rate.charge('principal-a', 'steel_scrape');

        await expect(rate.charge('principal-a', 'steel_session_release')).resolves.toBeUndefined();
    });
});

describe('per-principal isolation', () => {
    it('leaves every other principal untouched when one exhausts its budget', async () => {
        const { limiter: rate } = limiter();
        for (let call = 0; call < 10; call++) await rate.charge('noisy', 'steel_scrape');
        await expect(rate.charge('noisy', 'steel_scrape')).rejects.toThrow(/budget/);

        for (let call = 0; call < 10; call++) await rate.charge('quiet', 'steel_scrape');
        await expect(rate.charge('quiet', 'steel_scrape')).rejects.toThrow(/budget/);
        await expect(rate.charge('third', 'steel_session_create')).resolves.toBeUndefined();
    });
});

describe('refill on the injected clock', () => {
    it('restores budget as time passes, up to the burst ceiling', async () => {
        const { limiter: rate, time } = limiter();
        for (let call = 0; call < 10; call++) await rate.charge('principal-a', 'steel_scrape');
        await expect(rate.charge('principal-a', 'steel_scrape')).rejects.toThrow(/budget/);

        time.advanceSeconds(3);
        for (let call = 0; call < 3; call++) await rate.charge('principal-a', 'steel_scrape');
        await expect(rate.charge('principal-a', 'steel_scrape')).rejects.toThrow(/budget/);

        // An hour of idleness cannot bank more than one bucket of budget.
        time.advanceSeconds(3_600);
        for (let call = 0; call < 10; call++) await rate.charge('principal-a', 'steel_scrape');
        await expect(rate.charge('principal-a', 'steel_scrape')).rejects.toThrow(/budget/);
    });

    it('honours the retry-after it advertised', async () => {
        const { limiter: rate, time } = limiter();
        for (let call = 0; call < 10; call++) await rate.charge('principal-a', 'steel_scrape');

        const error = await rejection(() => rate.charge('principal-a', 'steel_batch'));
        expect(error.retryAfterSeconds).toBe(toolCost('steel_batch'));

        time.advanceSeconds(error.retryAfterSeconds ?? 0);
        await expect(rate.charge('principal-a', 'steel_batch')).resolves.toBeUndefined();
    });

    it('does not hand out free budget when the clock steps backwards', async () => {
        const { limiter: rate, time } = limiter();
        for (let call = 0; call < 10; call++) await rate.charge('principal-a', 'steel_scrape');

        time.advanceSeconds(-600);
        await expect(rate.charge('principal-a', 'steel_scrape')).rejects.toThrow(/budget/);
    });
});

describe('the rejection error', () => {
    it('names the limit, the cost, the refill rate and a concrete retry-after', async () => {
        const { limiter: rate } = limiter();
        for (let call = 0; call < 10; call++) await rate.charge('principal-a', 'steel_scrape');

        const error = await rejection(() => rate.charge('principal-a', 'steel_navigate'));

        expect(error.code).toBe('rate_limited');
        expect(error.message).toContain(RATE_LIMIT_NAME);
        expect(error.message).toContain('steel_navigate');
        expect(error.message).toMatch(/Retry after \d+s/);
        expect(error.message).toMatch(/60 units\/min/);
        expect(error.message).toMatch(/concurrent-session cap/);
        expect(error.message).toMatch(/20 requests\/min Browser Tools/);
        expect(error.message).toMatch(/steel_scrape/);
        expect(error.details).toMatchObject({ limit: RATE_LIMIT_NAME, tool: 'steel_navigate' });
    });

    it('says it is this server rejecting the call, not Steel', async () => {
        const { limiter: rate } = limiter();
        for (let call = 0; call < 10; call++) await rate.charge('principal-a', 'steel_scrape');

        const error = await rejection(() => rate.charge('principal-a', 'steel_scrape'));

        expect(error.message).toMatch(/not by Steel/);
    });

    it('renders as a tool-execution error carrying the retry-after', async () => {
        const { limiter: rate } = limiter();
        for (let call = 0; call < 10; call++) await rate.charge('principal-a', 'steel_scrape');

        const error = await rejection(() => rate.charge('principal-a', 'steel_snapshot'));
        const result = toolErrorResult(error);

        expect(result.isError).toBe(true);
        expect(result.content?.map(block => ('text' in block ? block.text : '')).join('\n')).toMatch(
            new RegExp(`Retry-After: ${error.retryAfterSeconds}s`)
        );
        expect(result.structuredContent).toMatchObject({
            error: { code: 'rate_limited', retryAfterSeconds: error.retryAfterSeconds },
        });
    });
});

// ABOUTME: Entrypoint-level OpenTelemetry wiring: starts an OTLP trace pipeline only when a standard
// ABOUTME: OTEL_ variable asks for one, so an unconfigured deployment loads no exporter at all.

/** A running trace pipeline, so an entrypoint can flush spans before the process exits. */
export interface TracingHandle {
    shutdown(): Promise<void>;
}

/** Starts a pipeline. Injected so a test can assert the wiring without an exporter or a collector. */
export type TracingStarter = (options: { serviceName: string }) => Promise<TracingHandle>;

export interface StartTracingOptions {
    start?: TracingStarter | undefined;
    /** Where a "tracing was asked for but could not start" message goes. */
    onWarn?: ((message: string) => void) | undefined;
}

/** The service name traces are attributed to when the operator does not choose one. */
const DEFAULT_SERVICE_NAME = 'steel-mcp';

/** Any of these, set to a non-blank value, means "export traces". */
const ENABLING_VARS = ['OTEL_EXPORTER_OTLP_ENDPOINT', 'OTEL_EXPORTER_OTLP_TRACES_ENDPOINT', 'OTEL_TRACES_EXPORTER'];

function setting(env: Record<string, string | undefined>, name: string): string {
    return env[name]?.trim() ?? '';
}

/** True when the environment asks for traces, following the standard OTEL variables. */
export function tracingRequested(env: Record<string, string | undefined>): boolean {
    if (setting(env, 'OTEL_SDK_DISABLED').toLowerCase() === 'true') return false;
    if (setting(env, 'OTEL_TRACES_EXPORTER').toLowerCase() === 'none') return false;
    return ENABLING_VARS.some(name => setting(env, name) !== '');
}

/**
 * Loads and starts the OTLP SDK.
 *
 * The imports are dynamic and the packages optional: the exporter stack is a large dependency tree
 * that an unconfigured server should never pay for, and one an operator may have omitted entirely.
 * NodeSDK reads the rest of its configuration — endpoint, headers, sampler, resource attributes —
 * from the standard OTEL variables, and registers the context manager span nesting needs.
 */
const startOtlpSdk: TracingStarter = async ({ serviceName }) => {
    const [{ NodeSDK }, { OTLPTraceExporter }] = await Promise.all([
        import('@opentelemetry/sdk-node'),
        import('@opentelemetry/exporter-trace-otlp-http'),
    ]);
    const sdk = new NodeSDK({ serviceName, traceExporter: new OTLPTraceExporter() });
    sdk.start();
    return { shutdown: () => sdk.shutdown() };
};

/**
 * Starts tracing if the environment asked for it, and answers with nothing if it did not.
 *
 * Called once per process, before serving: the stdio entrypoint does it on startup, and a hosted
 * deployment does it around whatever listens in front of `createSteelHttpHandler`. Nothing in the
 * core needs the handle — it resolves the registered tracer through the OpenTelemetry API — so the
 * handle exists only to flush spans on the way out.
 *
 * Failing to start is reported and then ignored: telemetry is never a reason to refuse to serve
 * browser sessions, and the core keeps working against the no-op tracer.
 */
export async function startTracing(
    env: Record<string, string | undefined>,
    options: StartTracingOptions = {}
): Promise<TracingHandle | undefined> {
    if (!tracingRequested(env)) return undefined;

    try {
        return await (options.start ?? startOtlpSdk)({
            serviceName: setting(env, 'OTEL_SERVICE_NAME') || DEFAULT_SERVICE_NAME,
        });
    } catch (error) {
        options.onWarn?.(
            'Tracing was requested but could not start, so this server is running without it. ' +
                'Install @opentelemetry/sdk-node and @opentelemetry/exporter-trace-otlp-http to enable it. ' +
                `(${error instanceof Error ? error.message : String(error)})`
        );
        return undefined;
    }
}

// ABOUTME: A minimal Chrome DevTools Protocol client over a WebSocket, plus the page-scoped session
// ABOUTME: interface every page operation is written against so tests can inject a fake.
import { WebSocket } from 'ws';
import { SteelToolError } from '../errors.js';

/** A CDP event payload. Shapes are protocol-defined; call sites narrow what they read. */
export type CdpEventParams = Record<string, unknown>;

/** A CDP connection scoped to one page target. All page operations depend on this, not on a socket. */
export interface CdpSession {
    send<T = unknown>(method: string, params?: Record<string, unknown>): Promise<T>;
    /** Subscribes to a CDP event; the returned function unsubscribes. */
    on(event: string, listener: (params: CdpEventParams) => void): () => void;
    close(): Promise<void>;
}

interface Pending {
    resolve(value: unknown): void;
    reject(error: Error): void;
    method: string;
}

interface CdpMessage {
    id?: number;
    method?: string;
    params?: CdpEventParams;
    sessionId?: string;
    result?: unknown;
    error?: { code: number; message: string; data?: string };
}

/** How long to wait for a single CDP command before giving up. */
const COMMAND_TIMEOUT_MS = 30_000;

/** A browser-level CDP connection that can attach page-scoped sessions over the same socket. */
export class CdpConnection {
    private readonly pending = new Map<number, Pending>();
    private readonly listeners = new Map<string, Set<(params: CdpEventParams, sessionId?: string) => void>>();
    private nextId = 1;
    private closed = false;

    private constructor(private readonly socket: WebSocket) {
        socket.on('message', raw => this.receive(String(raw)));
        socket.on('close', () => this.failAll('The CDP connection closed.'));
        socket.on('error', error => this.failAll(`The CDP connection failed: ${error.message}`));
    }

    /** True once the socket is gone, so a pool can evict this connection instead of reusing it. */
    get isClosed(): boolean {
        return this.closed;
    }

    /**
     * Opens a CDP connection.
     *
     * The signal cancels the handshake only. It deliberately does not survive into the established
     * connection: the signal belongs to one tool call, while the connection is pooled for the whole
     * browser session, so honouring a later abort would brick the session handle for every
     * subsequent call while Steel kept billing for the browser.
     */
    static async connect(url: string, signal?: AbortSignal): Promise<CdpConnection> {
        const socket = new WebSocket(url, { maxPayload: 256 * 1024 * 1024 });
        try {
            await new Promise<void>((resolve, reject) => {
                const onAbort = () => {
                    reject(
                        new SteelToolError('The request was cancelled before the browser connected.', {
                            code: 'timeout',
                        })
                    );
                };
                // The socket listeners are registered before the aborted check because terminate()
                // on a handshake that never opened makes ws emit 'error', and an emitter with no
                // 'error' listener turns that into an uncaught exception that would take the
                // process down. An already-aborted signal reaches terminate() by the shortest path,
                // so that path needs the listener too.
                socket.once('open', () => {
                    signal?.removeEventListener('abort', onAbort);
                    resolve();
                });
                socket.once('error', error => {
                    signal?.removeEventListener('abort', onAbort);
                    reject(
                        new SteelToolError(`Could not open a browser connection: ${error.message}`, {
                            code: 'steel_error',
                        })
                    );
                });
                if (signal?.aborted) {
                    onAbort();
                    return;
                }
                signal?.addEventListener('abort', onAbort, { once: true });
            });
        } catch (error) {
            socket.terminate();
            throw error;
        }

        return new CdpConnection(socket);
    }

    private receive(raw: string): void {
        let message: CdpMessage;
        try {
            message = JSON.parse(raw) as CdpMessage;
        } catch {
            return;
        }

        if (message.id !== undefined) {
            const pending = this.pending.get(message.id);
            if (!pending) return;
            this.pending.delete(message.id);
            if (message.error) {
                pending.reject(
                    new SteelToolError(`${pending.method} failed: ${message.error.message}`, { code: 'steel_error' })
                );
            } else {
                pending.resolve(message.result);
            }
            return;
        }

        if (message.method) {
            for (const listener of this.listeners.get(message.method) ?? []) {
                listener(message.params ?? {}, message.sessionId);
            }
        }
    }

    private failAll(reason: string): void {
        this.closed = true;
        for (const pending of this.pending.values()) {
            pending.reject(new SteelToolError(reason, { code: 'steel_error' }));
        }
        this.pending.clear();
    }

    /** Sends a CDP command, optionally targeting an attached page session. */
    async send<T = unknown>(method: string, params: Record<string, unknown> = {}, sessionId?: string): Promise<T> {
        if (this.closed) {
            throw new SteelToolError('The browser connection is closed. Create a new session.', {
                code: 'session_expired',
            });
        }
        const id = this.nextId++;
        const payload = JSON.stringify(sessionId ? { id, method, params, sessionId } : { id, method, params });

        return new Promise<T>((resolve, reject) => {
            const timer = setTimeout(() => {
                this.pending.delete(id);
                reject(
                    new SteelToolError(`${method} did not answer within ${COMMAND_TIMEOUT_MS}ms.`, { code: 'timeout' })
                );
            }, COMMAND_TIMEOUT_MS);

            this.pending.set(id, {
                method,
                resolve: value => {
                    clearTimeout(timer);
                    resolve(value as T);
                },
                reject: error => {
                    clearTimeout(timer);
                    reject(error);
                },
            });
            this.socket.send(payload);
        });
    }

    /** Subscribes to a CDP event across every session on this connection. */
    on(event: string, listener: (params: CdpEventParams, sessionId?: string) => void): () => void {
        const set = this.listeners.get(event) ?? new Set();
        set.add(listener);
        this.listeners.set(event, set);
        return () => set.delete(listener);
    }

    /**
     * Attaches to the first page target and returns a session bound to it.
     *
     * Only one page is ever attached: eagerly attaching to every target is how a long-lived
     * browser connection exhausts memory on a site that opens many tabs.
     */
    async attachToPage(): Promise<CdpSession> {
        const { targetInfos } = await this.send<{ targetInfos: Array<{ targetId: string; type: string }> }>(
            'Target.getTargets'
        );
        const page = targetInfos.find(target => target.type === 'page');
        if (!page) {
            throw new SteelToolError('The browser session has no open page to attach to.', { code: 'steel_error' });
        }
        const { sessionId } = await this.send<{ sessionId: string }>('Target.attachToTarget', {
            targetId: page.targetId,
            flatten: true,
        });
        return new AttachedCdpSession(this, sessionId);
    }

    async close(): Promise<void> {
        if (this.closed) return;
        this.closed = true;
        this.socket.close();
        this.failAll('The CDP connection was closed by this server.');
    }
}

/** A page-scoped view of a browser connection: every command and event carries the target session. */
class AttachedCdpSession implements CdpSession {
    constructor(
        private readonly connection: CdpConnection,
        private readonly sessionId: string
    ) {}

    send<T = unknown>(method: string, params: Record<string, unknown> = {}): Promise<T> {
        return this.connection.send<T>(method, params, this.sessionId);
    }

    on(event: string, listener: (params: CdpEventParams) => void): () => void {
        return this.connection.on(event, (params, sessionId) => {
            if (sessionId === this.sessionId) listener(params);
        });
    }

    async close(): Promise<void> {
        await this.connection.close();
    }
}
